-- CI/merge and observed deployed media hashes. Caller must set the batch gate.
DO $pina_colada$
DECLARE
 j constant jsonb := $records$[{"id":"1b078b4e-6544-41d5-8e9c-52e6d8fa3d8e","recipe_group_id":"e91765d0-3d25-4790-a08f-89ce82446332","slug":"receta-de-pina-colada","public_path":"/receta-de-pina-colada","source_url":"https://manualdecocina.com/receta-de-pina-colada/","language":"es","title":"Piña colada batida con ron y crema de coco","excerpt":"Piña fresca, zumo, crema de coco endulzada y ron en gramos: dos raciones propuestas y hielo medido para una piña colada batida.","summary":"Piña colada propuesta con piña fresca y zumo, crema de coco endulzada, ron blanco e hielo medido. Se plantean 2 raciones y 15 minutos de preparación sin cocción. Contiene alcohol; cantidades, textura y rendimiento siguen pendientes de prueba en cocina. La nutrición incluye la energía del ron y excluye adornos.","category":"Bebidas","category_slug":"bebidas","difficulty":"Fácil","course":"Bebida","cuisine":"Inspiración puertorriqueña","prep_time_minutes":15,"cook_time_minutes":0,"total_time_minutes":15,"servings":2,"ingredients":[{"name":"piña fresca, pulpa limpia sin piel, ojos ni centro duro","amount":"120","unit":"g","group":"Fruta"},{"name":"zumo de piña envasado sin azúcar añadido, no concentrado sin diluir","amount":"180","unit":"g","group":"Fruta"},{"name":"crema de coco endulzada para cócteles, no leche de coco ni crema natural sin azúcar","amount":"60","unit":"g","group":"Base de coco"},{"name":"ron blanco de 40 % vol., equivalente a 80 proof; cantidad pesada, no mililitros","amount":"60","unit":"g","group":"Con alcohol"},{"name":"hielo picado elaborado con agua potable","amount":"180","unit":"g","group":"Frío"}],"steps":[{"title":"Reúne y pesa los ingredientes","content":"Prepara una báscula, tabla y cuchillo limpios, una batidora apta para hielo picado y dos vasos limpios de capacidad suficiente. Mide 180 g de zumo de piña envasado sin azúcar añadido, 60 g de crema de coco endulzada para cócteles, 60 g de ron blanco de 40 % vol. y 180 g de hielo picado de agua potable. Reserva la piña para obtener después 120 g de pulpa limpia. El ron se pesa en gramos; 60 g no se presentan como 60 ml. Usa envases intactos y dentro de fecha. No añadas azúcar, jarabe, leche, nata, lima ni adornos fuera de esta fórmula. Sigue las instrucciones de tu batidora y no uses hielo si el equipo no está diseñado para triturarlo.","image_url":"/recetas/receta-de-pina-colada/paso-01.webp","image_alt":"Piña colada: Reúne y pesa los ingredientes"},{"title":"Lava y corta la piña","content":"Lava la piña bajo agua potable antes de pelarla, sin jabón ni detergente, y seca el exterior con material limpio. Retira piel, ojos y el centro duro sobre una tabla estable; descarta zonas dañadas y no uses fruta podrida. Pesa 120 g de pulpa comestible y córtala en dados de unos 2 cm. Esa cantidad no incluye piel ni corazón y se usa completa en la bebida, sin reservar una rodaja de adorno. Mantén tabla, cuchillo y manos limpios, separados de carnes crudas. El zumo se usa envasado y listo para beber, no como concentrado sin diluir.","image_url":"/recetas/receta-de-pina-colada/paso-02.webp","image_alt":"Piña colada: Lava y corta la piña"},{"title":"Tritura la fruta con el coco y el zumo","content":"Remueve la crema de coco endulzada con una cuchara limpia si tiene fases separadas; no la confundas con leche de coco ni crema sin azúcar. Con la batidora parada, coloca los 180 g de zumo, los 60 g de crema de coco y los 120 g de piña en su jarra. Cierra la tapa y tritura unos 30–45 segundos hasta que no queden trozos grandes. Si necesitas recoger lo pegado, detén y desconecta antes de abrir; no introduzcas manos ni utensilios junto a cuchillas en movimiento. Todavía no añadas el ron ni el hielo; no cueles la fruta, porque la pulpa completa está incluida en la nutrición.","image_url":"/recetas/receta-de-pina-colada/paso-03.webp","image_alt":"Piña colada: Tritura la fruta con el coco y el zumo"},{"title":"Añade ron y hielo, y termina de batir","content":"Detén y desconecta antes de abrir. Añade los 60 g de ron blanco y los 180 g de hielo picado medidos, sin agregar hielo o agua extra. Cierra bien la tapa y bate unos 30–60 segundos, con las pausas indicadas por el fabricante, hasta una bebida uniforme y fría con textura de granizado fino. No metas una cuchara para ayudar mientras esté en marcha ni sobrecargues la jarra. Si el equipo requiere más pausas o una tanda adicional, cuenta ese tiempo real. El triturado no elimina el alcohol; esta versión lo contiene y no se presenta como bebida sin alcohol.","image_url":"/recetas/receta-de-pina-colada/paso-04.webp","image_alt":"Piña colada: Añade ron y hielo, y termina de batir"},{"title":"Reparte sin añadir adornos","content":"Detén y desconecta la batidora. Comprueba con una cuchara limpia, fuera del equipo en marcha, que no haya grandes trozos de hielo o fruta; si los hay, vuelve a cerrar y tritura el tiempo necesario. Reparte toda la mezcla en 2 vasos de al menos 350 ml de capacidad, alternando pequeñas cantidades para distribuir la pulpa y el hielo de forma similar. Cada ración propuesta es aproximadamente la mitad del lote; no afirmes que se han medido gramos ni volumen finales. No añadas rodajas de piña, cerezas, nata, azúcar o hielo de servicio a la nutrición de esta fórmula. La espuma o una ligera separación no prueban fallo ni garantizan una textura ensayada.","image_url":"/recetas/receta-de-pina-colada/paso-05.webp","image_alt":"Piña colada: Reparte sin añadir adornos"},{"title":"Sirve de inmediato y registra los tiempos reales","content":"Sirve las 2 raciones enseguida con utensilios limpios. La propuesta estima 15 minutos de preparación, 0 de cocción y 15 minutos en total, incluyendo lavado, corte, pesaje, triturado y reparto; añade cualquier pausa o tanda adicional real. No se exige reposo ni se afirma prueba de cocina. Si no se consume enseguida, guarda la mezcla tapada a 4 °C o menos y úsala dentro de 1 día; al descongelarse el hielo y separarse el coco perderá textura y necesitará mezclarse de nuevo. Refrigera dentro de 2 horas fuera del frío, o 1 hora si el ambiente supera 32 °C. El alcohol no sustituye la higiene ni convierte la bebida en una conserva estable. Identifica claramente la versión con ron.","image_url":"/recetas/receta-de-pina-colada/portada.webp","image_alt":"Piña colada: Sirve de inmediato y registra los tiempos reales"}],"notes":"Piña colada batida propuesta con piña fresca, zumo, crema de coco endulzada y ron; no se presenta como reproducción exacta de las proporciones IBA ni como receta probada. Contiene alcohol y se identifica como bebida para adultos; batir o refrigerar no lo elimina. La variante sin ron debe prepararse y rotularse por separado, con nuevas cantidades y cálculo nutricional; no se reutilizan estas cifras. La crema de coco endulzada para cócteles no equivale a leche de coco ni a crema natural: revisa el envase y posibles alérgenos o ingredientes lácteos añadidos de cada marca. El hielo debe proceder de agua potable y la batidora estar diseñada para él. Nunca abras ni rasques cerca de cuchillas en movimiento; detén y desconecta primero. Lava la piña antes de pelar y mantén los utensilios separados de carne cruda. Sirve enseguida; para sobrantes usa recipientes tapados a 4 °C o menos y consume dentro de 1 día, con pérdida de textura. Refrigera dentro de 2 horas fuera del frío o 1 hora si el ambiente supera 32 °C. El ron no conserva la bebida de forma estable. Cambios de crema, zumo, ron o hielo se anotan y recalculan; adornos se calculan aparte. Dos raciones y 15 minutos son propuestas pendientes de cocina, no rendimiento ni tiempos confirmados.","nutrition":{"calories":254.1,"protein_g":1.0,"carbs_g":35.4,"fat_g":5.1,"saturated_fat_g":4.7,"sodium_mg":13.5,"fiber_g":1.1,"sugar_g":30.3,"alcohol_g":10.0,"estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"piña fresca,120 g netos sin piel ni centro duro","edible_grams":120,"fdc_id":169124,"fdc_description":"Pineapple, raw, all varieties","per_100g":{"protein_g":0.54,"sodium_mg":1.0,"sugar_g":9.85,"fat_g":0.12,"fiber_g":1.4,"saturated_fat_g":0.009,"carbs_g":13.1,"calories":50.0,"alcohol_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/169124/nutrients"},{"ingredient":"zumo de piña envasado sin azúcar añadido, sin concentrar","edible_grams":180,"fdc_id":169947,"fdc_description":"Pineapple juice, canned or bottled, unsweetened, without added ascorbic acid","per_100g":{"saturated_fat_g":0.008,"carbs_g":12.9,"calories":53.0,"alcohol_g":0.0,"fat_g":0.12,"sugar_g":9.98,"fiber_g":0.2,"sodium_mg":2.0,"protein_g":0.36},"source_url":"https://fdc.nal.usda.gov/food-details/169947/nutrients"},{"ingredient":"crema de coco enlatada ENDULZADA para cócteles","edible_grams":60,"fdc_id":170171,"fdc_description":"Nuts, coconut cream, canned, sweetened","per_100g":{"alcohol_g":0.0,"saturated_fat_g":15.5,"fiber_g":0.2,"protein_g":1.17,"sodium_mg":36.0,"sugar_g":51.5,"fat_g":16.3,"carbs_g":53.2,"calories":357},"source_url":"https://fdc.nal.usda.gov/food-details/170171/nutrients"},{"ingredient":"ron blanco80proof/40%vol,60g pesados","edible_grams":60,"fdc_id":174817,"fdc_description":"Alcoholic beverage, distilled, rum, 80 proof","per_100g":{"fiber_g":0.0,"sodium_mg":1.0,"protein_g":0.0,"alcohol_g":33.4,"saturated_fat_g":0.0,"fat_g":0.0,"carbs_g":0.0,"calories":231,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/174817/nutrients"}],"serving_size":"La mitad del lote; 2 raciones propuestas","method":"Cuatro fichas USDA verificadas: gramos comestibles por nutrientes por 100 g, sumados y divididos entre 2. Piña fresca FDC 169124, zumo envasado sin azúcar añadido FDC 169947, crema de coco ENDULZADA FDC 170171 y ron de 80 proof FDC 174817. Incluye la energía del alcohol indicada por USDA; no se calcula solo con proteínas, grasas y carbohidratos. Hielo 180 g de agua potable sin aporte en estos campos.","note":"Estimación, no análisis ni rendimiento confirmado. Incluye todo el ron, sin modelar evaporación ni eliminación por batido. Alcohol estimado 10,0 g por ración a partir de la ficha de ron, no medición de graduación final ni promesa de consumo seguro. La crema de coco dulce difiere de leche o crema natural sin azúcar; la marca, azúcar, graduación y cantidades cambian los valores. Pulpa completa sin colar; los 180 g de hielo se incluyen solo en la suma de peso inicial de 600 g, no en un volumen final medido. No se afirman 300 g servidos comprobados. Sin adornos ni acompañamientos; todos los datos están presentes, sin convertir ausencias en cero."},"keywords":["piña colada con ron","piña colada batida","crema de coco endulzada","cóctel de piña"],"image_url":"/recetas/receta-de-pina-colada/portada.webp","gallery":["/recetas/receta-de-pina-colada/paso-01.webp","/recetas/receta-de-pina-colada/paso-02.webp","/recetas/receta-de-pina-colada/paso-03.webp","/recetas/receta-de-pina-colada/paso-04.webp","/recetas/receta-de-pina-colada/paso-05.webp"],"seo":{"title":"Piña colada con ron: cantidades y pasos para batir","description":"Piña colada batida con piña fresca, zumo, crema de coco dulce, ron e hielo medido. Dos raciones propuestas, pasos y cálculo con el alcohol incluido.","image_alt":"Dos vasos transparentes de piña colada batida, de color amarillo pálido y textura fría cremosa, sin rodajas, cerezas ni nata añadida","image_variants":["/recetas/receta-de-pina-colada/portada-1x1.webp","/recetas/receta-de-pina-colada/portada-4x3.webp","/recetas/receta-de-pina-colada/portada-16x9.webp"],"faq":[{"q":"¿La crema de coco endulzada equivale a leche de coco?","a":"No. Esta fórmula usa 60 g de crema de coco endulzada para cócteles, con ficha USDA específica. Leche de coco, crema natural sin azúcar o nata cambian azúcar, grasa, sabor y textura; no se sustituyen manteniendo estas mismas cifras."},{"q":"¿Puedo hacer una versión sin alcohol?","a":"Sí, como variante separada: omite el ron, define y anota la cantidad de líquido que uses en su lugar y recalcula. No añadas ron al lote destinado a esa variante ni lo llames sin alcohol tras batir: el triturado no elimina el alcohol. No se asignan a la variante las calorías de esta fórmula."},{"q":"¿Por qué queda más líquida después de esperar?","a":"El hielo se derrite y el coco puede separarse. Sirve recién batida y no añadas agua o hielo extra sin registrarlo. La propuesta usa 180 g de hielo para el lote; cambios modifican dilución y peso de cada porción. No se promete textura idéntica entre batidoras y marcas."}]},"published":true,"editorial_status":"published","content_html":"<p>Piña colada propuesta con piña fresca y zumo, crema de coco endulzada, ron blanco e hielo medido. Se plantean 2 raciones y 15 minutos de preparación sin cocción. Contiene alcohol; cantidades, textura y rendimiento siguen pendientes de prueba en cocina. La nutrición incluye la energía del ron y excluye adornos.</p><p>Piña colada batida propuesta con piña fresca, zumo, crema de coco endulzada y ron; no se presenta como reproducción exacta de las proporciones IBA ni como receta probada. Contiene alcohol y se identifica como bebida para adultos; batir o refrigerar no lo elimina. La variante sin ron debe prepararse y rotularse por separado, con nuevas cantidades y cálculo nutricional; no se reutilizan estas cifras. La crema de coco endulzada para cócteles no equivale a leche de coco ni a crema natural: revisa el envase y posibles alérgenos o ingredientes lácteos añadidos de cada marca. El hielo debe proceder de agua potable y la batidora estar diseñada para él. Nunca abras ni rasques cerca de cuchillas en movimiento; detén y desconecta primero. Lava la piña antes de pelar y mantén los utensilios separados de carne cruda. Sirve enseguida; para sobrantes usa recipientes tapados a 4 °C o menos y consume dentro de 1 día, con pérdida de textura. Refrigera dentro de 2 horas fuera del frío o 1 hora si el ambiente supera 32 °C. El ron no conserva la bebida de forma estable. Cambios de crema, zumo, ron o hielo se anotan y recalculan; adornos se calculan aparte. Dos raciones y 15 minutos son propuestas pendientes de cocina, no rendimiento ni tiempos confirmados.</p>"},{"id":"4c610392-173c-5b47-b0b9-737436ecc577","recipe_group_id":"e91765d0-3d25-4790-a08f-89ce82446332","slug":"pina-colada-rezept","public_path":"/de/pina-colada-rezept","source_url":"https://manualdecocina.com/de/pina-colada-rezept/","language":"de","title":"Gemixte Piña Colada mit Rum und Kokoscreme","excerpt":"Frische Ananas, Saft, gesüßte Kokoscreme und Rum in Gramm: zwei vorgeschlagene Portionen mit abgewogenem zerstoßenem Eis.","summary":"Piña-Colada-Vorschlag mit frischer Ananas, Saft, gesüßter Kokoscreme, weißem Rum und abgewogenem Eis. Vorgesehen sind 2 Portionen und 15 Minuten Zubereitung ohne Kochen. Enthält Alkohol; Mengen, Konsistenz und Ausbeute sind noch nicht in der Küche geprüft. Die Nährwerte enthalten die Energie des Rums und keine Garnitur.","category":"Getränke","category_slug":"bebidas","difficulty":"Einfach","course":"Getränk","cuisine":"Puerto-ricanisch inspiriert","prep_time_minutes":15,"cook_time_minutes":0,"total_time_minutes":15,"servings":2,"ingredients":[{"name":"frische Ananas, Fruchtfleisch ohne Schale, Augen und harten Strunk","amount":"120","unit":"g","group":"Frucht"},{"name":"abgefüllter Ananassaft ohne Zuckerzusatz, kein unverdünntes Konzentrat","amount":"180","unit":"g","group":"Frucht"},{"name":"gesüßte Kokoscreme für Cocktails, keine Kokosmilch oder ungesüßte Naturcreme","amount":"60","unit":"g","group":"Kokosbasis"},{"name":"weißer Rum mit 40 % vol., entsprechend 80 proof; gewogen, nicht in Millilitern gemessen","amount":"60","unit":"g","group":"Mit Alkohol"},{"name":"zerstoßenes Eis aus Trinkwasser","amount":"180","unit":"g","group":"Kühlung"}],"steps":[{"title":"Zutaten bereitstellen und wiegen","content":"Waage, sauberes Brett und Messer, einen für zerstoßenes Eis geeigneten Mixer und zwei ausreichend große saubere Gläser bereitstellen. 180 g abgefüllten Ananassaft ohne Zuckerzusatz, 60 g gesüßte Cocktail-Kokoscreme, 60 g weißen Rum mit 40 % vol. und 180 g zerstoßenes Trinkwassereis abmessen. Genügend Ananas für später 120 g sauberes Fruchtfleisch vorsehen. Rum wird in Gramm gewogen: 60 g werden nicht als 60 ml dargestellt. Unbeschädigte, haltbare Verpackungen verwenden. Keinen Zucker, Sirup, Milch, Sahne, Limette oder zusätzliche Garnitur zugeben. Mixeranleitung beachten und Eis nur in dafür vorgesehenen Geräten verwenden.","image_url":"/recetas/receta-de-pina-colada/paso-01.webp","image_alt":"Ananas, Saft, gesüßte Kokoscreme, Rum und zerstoßenes Eis neben leerem Mixer"},{"title":"Ananas waschen und schneiden","content":"Ananas vor dem Schälen unter Trinkwasser ohne Seife oder Spülmittel waschen und außen sauber trocknen. Auf einem stabilen Brett Schale, Augen und harten Strunk entfernen; beschädigte Stellen wegschneiden und keine verdorbene Frucht verwenden. 120 g essbares Fruchtfleisch wiegen und in ungefähr 2 cm große Stücke schneiden. Schale und Strunk zählen nicht dazu; alles kommt in das Getränk, keine Scheibe als Garnitur zurückbehalten. Brett, Messer und Hände sauber und von rohem Fleisch getrennt halten. Trinkfertigen abgefüllten Saft verwenden, kein unverdünntes Konzentrat.","image_url":"/recetas/receta-de-pina-colada/paso-02.webp","image_alt":"Saubere Hände schneiden geschälte Ananas auf stabilem Brett, Schale separat"},{"title":"Frucht, Kokoscreme und Saft mixen","content":"Getrennte Phasen der gesüßten Kokoscreme mit sauberem Löffel verrühren; nicht mit Kokosmilch oder ungesüßter Creme verwechseln. Bei gestopptem Mixer 180 g Saft, 60 g Kokoscreme und 120 g Ananas in den Behälter geben. Deckel schließen und etwa 30–45 Sekunden mixen, bis keine großen Fruchtstücke bleiben. Vor Öffnen und Abschaben stoppen und Stecker ziehen; keine Hände oder Utensilien an laufende Klingen bringen. Rum und Eis noch nicht zugeben. Die Frucht nicht durchsieben, denn das gesamte Fruchtfleisch ist eingerechnet.","image_url":"/recetas/receta-de-pina-colada/paso-03.webp","image_alt":"Frucht, Saft und Kokoscreme im gestoppten Mixer vor Rum und Eis"},{"title":"Rum und Eis zugeben und fertig mixen","content":"Vor dem Öffnen stoppen und Stecker ziehen. Abgewogene 60 g weißen Rum und 180 g zerstoßenes Eis zugeben, ohne zusätzliches Eis oder Wasser. Deckel fest schließen und etwa 30–60 Sekunden mit vorgeschriebenen Gerätepausen mixen, bis das Getränk gleichmäßig kalt und fein eisig ist. Nicht bei laufendem Mixer mit einem Löffel nachhelfen und Behälter nicht überladen. Zusätzliche Pausen oder weitere Durchgänge als tatsächliche Zeit anrechnen. Mixen entfernt keinen Alkohol; diese Version enthält ihn und wird nicht als alkoholfrei bezeichnet.","image_url":"/recetas/receta-de-pina-colada/paso-04.webp","image_alt":"Geschlossener Mixer mit Ananas-Kokos-Masse und zerstoßenem Eis"},{"title":"Ohne zusätzliche Garnitur aufteilen","content":"Mixer stoppen und vom Strom trennen. Mit sauberem Löffel außerhalb des laufenden Geräts auf große Eis- oder Fruchtstücke prüfen; nötigenfalls erneut schließen und ausreichend mixen. Die gesamte Masse auf 2 Gläser mit mindestens 350 ml Fassungsvermögen verteilen, dabei kleine Mengen abwechselnd eingießen, damit Fruchtfleisch und Eis ähnlich verteilt sind. Eine vorgeschlagene Portion ist ungefähr die Hälfte des Ansatzes, kein bestätigtes Endgewicht oder Volumen. Ananasscheiben, Kirschen, Sahne, Zucker oder weiteres Serviereis sind nicht eingerechnet. Schaum oder leichte Trennung beweisen keinen Fehler und garantieren keine erprobte Konsistenz.","image_url":"/recetas/receta-de-pina-colada/paso-05.webp","image_alt":"Abgenommener gestoppter Mixerbehälter gießt in eines von zwei Gläsern"},{"title":"Sofort servieren und tatsächliche Zeiten notieren","content":"Die 2 Portionen sofort mit sauberen Utensilien servieren. Vorgeschlagen sind 15 Minuten Vorbereitung, 0 Minuten Kochen und 15 Minuten insgesamt, einschließlich Waschen, Schneiden, Wiegen, Mixen und Aufteilen; tatsächliche Zusatzpausen oder Durchgänge addieren. Keine Ruhezeit und keine Küchenprüfung behaupten. Bei verzögertem Verzehr abgedeckt bei höchstens 4 °C lagern und innerhalb von 1 Tag verwenden; schmelzendes Eis und getrennte Kokoscreme verändern die Textur und erfordern erneutes Vermischen. Innerhalb von 2 Stunden außerhalb der Kühlung kühlen, bei über 32 °C Umgebung innerhalb von 1 Stunde. Alkohol ersetzt keine Hygiene und macht daraus keine ungekühlt haltbare Konserve. Rumversion deutlich kennzeichnen.","image_url":"/recetas/receta-de-pina-colada/portada.webp","image_alt":"Zwei Gläser blassgelbe Piña Colada ohne Garnitur oder Sahne"}],"notes":"Gemixter Piña-Colada-Vorschlag mit Frucht, Saft, gesüßter Kokoscreme und Rum, keine exakte Wiedergabe der IBA-Verhältnisse oder geprüfte Rezeptur. Enthält Alkohol und ist als Getränk für Erwachsene gekennzeichnet; Mixen und Kühlen entfernen ihn nicht. Rumfreie Varianten getrennt herstellen und beschriften, Mengen festlegen und neu berechnen statt diese Zahlen zu übernehmen. Gesüßte Cocktail-Kokoscreme unterscheidet sich von Kokosmilch und Naturcreme: Verpackungen auf Allergene und zugesetzte Milchprodukte prüfen. Trinkwassereis und dafür geeigneten Mixer verwenden. Vor Öffnen oder Abschaben an Klingen stoppen und Stecker ziehen. Ananas vor dem Schälen waschen, Geräte von rohem Fleisch trennen. Sofort servieren; Reste abgedeckt bei höchstens 4 °C lagern und innerhalb von 1 Tag verbrauchen, mit Texturverlust. Innerhalb von 2 Stunden außerhalb der Kühlung kühlen oder innerhalb von 1 Stunde bei über 32 °C. Rum macht das Getränk nicht ungekühlt haltbar. Änderungen an Creme, Saft, Rum und Eis notieren und neu berechnen; Garnitur separat rechnen. Zwei Portionen und 15 Minuten sind ungeprüfte Vorschläge.","nutrition":{"calories":254.1,"protein_g":1.0,"carbs_g":35.4,"fat_g":5.1,"saturated_fat_g":4.7,"sodium_mg":13.5,"fiber_g":1.1,"sugar_g":30.3,"alcohol_g":10.0,"estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"piña fresca,120 g netos sin piel ni centro duro","edible_grams":120,"fdc_id":169124,"fdc_description":"Pineapple, raw, all varieties","per_100g":{"protein_g":0.54,"sodium_mg":1.0,"sugar_g":9.85,"fat_g":0.12,"fiber_g":1.4,"saturated_fat_g":0.009,"carbs_g":13.1,"calories":50.0,"alcohol_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/169124/nutrients"},{"ingredient":"zumo de piña envasado sin azúcar añadido, sin concentrar","edible_grams":180,"fdc_id":169947,"fdc_description":"Pineapple juice, canned or bottled, unsweetened, without added ascorbic acid","per_100g":{"saturated_fat_g":0.008,"carbs_g":12.9,"calories":53.0,"alcohol_g":0.0,"fat_g":0.12,"sugar_g":9.98,"fiber_g":0.2,"sodium_mg":2.0,"protein_g":0.36},"source_url":"https://fdc.nal.usda.gov/food-details/169947/nutrients"},{"ingredient":"crema de coco enlatada ENDULZADA para cócteles","edible_grams":60,"fdc_id":170171,"fdc_description":"Nuts, coconut cream, canned, sweetened","per_100g":{"alcohol_g":0.0,"saturated_fat_g":15.5,"fiber_g":0.2,"protein_g":1.17,"sodium_mg":36.0,"sugar_g":51.5,"fat_g":16.3,"carbs_g":53.2,"calories":357},"source_url":"https://fdc.nal.usda.gov/food-details/170171/nutrients"},{"ingredient":"ron blanco80proof/40%vol,60g pesados","edible_grams":60,"fdc_id":174817,"fdc_description":"Alcoholic beverage, distilled, rum, 80 proof","per_100g":{"fiber_g":0.0,"sodium_mg":1.0,"protein_g":0.0,"alcohol_g":33.4,"saturated_fat_g":0.0,"fat_g":0.0,"carbs_g":0.0,"calories":231,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/174817/nutrients"}],"serving_size":"Die Hälfte des Ansatzes; 2 vorgeschlagene Portionen","method":"Vier geprüfte USDA-Einträge: essbare Gramm mal Nährstoffe je 100 g, summiert und durch 2 geteilt. Frische Ananas FDC 169124, abgefüllter ungesüßter Saft FDC 169947, GESÜSSTE Kokoscreme FDC 170171 und Rum 80 proof FDC 174817. USDA-Energie enthält Alkohol; nicht nur Eiweiß, Fett und Kohlenhydrate berechnen. Trinkwassereis 180 g liefert in diesen Feldern keinen Beitrag.","note":"Schätzung, keine Analyse oder bestätigte Ausbeute. Der gesamte Rum ist enthalten, ohne angenommene Verdunstung oder Entfernung durch Mixen. Geschätzter Alkohol 10,0 g je Portion aus dem Rumeintrag, keine gemessene Endgraduierung oder Behauptung sicheren Konsums. Gesüßte Kokoscreme ist nicht Naturcreme oder Milch; Marke, Zucker, Alkoholstärke und Mengen ändern die Werte. Gesamtes Fruchtfleisch ohne Sieben. Eis 180 g zählt nur zur anfänglichen Gewichtssumme 600 g, nicht zu gemessenem Endvolumen oder bestätigten 300 g pro Portion. Ohne Garnitur und Beilagen; alle Daten vorhanden, Fehlwerte nicht als null behandeln."},"keywords":["Piña Colada mit Rum","gemixte Piña Colada","gesüßte Kokoscreme","Ananascocktail"],"image_url":"/recetas/receta-de-pina-colada/portada.webp","gallery":["/recetas/receta-de-pina-colada/paso-01.webp","/recetas/receta-de-pina-colada/paso-02.webp","/recetas/receta-de-pina-colada/paso-03.webp","/recetas/receta-de-pina-colada/paso-04.webp","/recetas/receta-de-pina-colada/paso-05.webp"],"seo":{"title":"Piña Colada mit Rum: Mengen und Mixanleitung","description":"Frische Ananas, Saft, gesüßte Kokoscreme, weißer Rum und abgewogenes Eis: zwei vorgeschlagene Portionen mit Mixschritten und Nährwerten inklusive Alkohol.","image_alt":"Zwei klare Gläser blassgelbe cremige eisige Piña Colada ohne Ananasscheiben, Kirschen oder zugesetzte Sahne","image_variants":["/recetas/receta-de-pina-colada/portada-1x1.webp","/recetas/receta-de-pina-colada/portada-4x3.webp","/recetas/receta-de-pina-colada/portada-16x9.webp"],"faq":[{"q":"Ist gesüßte Kokoscreme dasselbe wie Kokosmilch?","a":"Nein. Hier werden 60 g gesüßte Cocktail-Kokoscreme mit spezifischem USDA-Eintrag verwendet. Kokosmilch, ungesüßte Creme und Sahne verändern Zucker, Fett, Geschmack und Textur; beim Austausch nicht dieselben Zahlen beibehalten."},{"q":"Kann ich eine alkoholfreie Version machen?","a":"Ja, als getrennte Variante: Rum weglassen, Ersatzflüssigkeit und Menge festlegen, notieren und neu berechnen. Keinen Rum in diese Variante geben oder einen Rumdrink nach dem Mixen alkoholfrei nennen: Mixen entfernt keinen Alkohol. Die hier berechneten Kalorien gelten nicht für die andere Rezeptur."},{"q":"Warum wird das Getränk beim Warten dünner?","a":"Eis schmilzt und Kokoscreme kann sich trennen. Frisch gemixt servieren; zusätzliches Wasser oder Eis dokumentieren. Vorgesehen sind 180 g Eis im Ansatz; Änderungen beeinflussen Verdünnung und Portionsgewicht. Identische Textur verschiedener Geräte und Marken wird nicht versprochen."}]},"published":true,"editorial_status":"published","content_html":"<p>Piña-Colada-Vorschlag mit frischer Ananas, Saft, gesüßter Kokoscreme, weißem Rum und abgewogenem Eis. Vorgesehen sind 2 Portionen und 15 Minuten Zubereitung ohne Kochen. Enthält Alkohol; Mengen, Konsistenz und Ausbeute sind noch nicht in der Küche geprüft. Die Nährwerte enthalten die Energie des Rums und keine Garnitur.</p><p>Gemixter Piña-Colada-Vorschlag mit Frucht, Saft, gesüßter Kokoscreme und Rum, keine exakte Wiedergabe der IBA-Verhältnisse oder geprüfte Rezeptur. Enthält Alkohol und ist als Getränk für Erwachsene gekennzeichnet; Mixen und Kühlen entfernen ihn nicht. Rumfreie Varianten getrennt herstellen und beschriften, Mengen festlegen und neu berechnen statt diese Zahlen zu übernehmen. Gesüßte Cocktail-Kokoscreme unterscheidet sich von Kokosmilch und Naturcreme: Verpackungen auf Allergene und zugesetzte Milchprodukte prüfen. Trinkwassereis und dafür geeigneten Mixer verwenden. Vor Öffnen oder Abschaben an Klingen stoppen und Stecker ziehen. Ananas vor dem Schälen waschen, Geräte von rohem Fleisch trennen. Sofort servieren; Reste abgedeckt bei höchstens 4 °C lagern und innerhalb von 1 Tag verbrauchen, mit Texturverlust. Innerhalb von 2 Stunden außerhalb der Kühlung kühlen oder innerhalb von 1 Stunde bei über 32 °C. Rum macht das Getränk nicht ungekühlt haltbar. Änderungen an Creme, Saft, Rum und Eis notieren und neu berechnen; Garnitur separat rechnen. Zwei Portionen und 15 Minuten sind ungeprüfte Vorschläge.</p>"},{"id":"cd56cf87-ddce-549d-9587-448d7f6c128a","recipe_group_id":"e91765d0-3d25-4790-a08f-89ce82446332","slug":"pina-colada-recipe","public_path":"/en/pina-colada-recipe","source_url":"https://manualdecocina.com/en/pina-colada-recipe/","language":"en","title":"Blended piña colada with rum and coconut cream","excerpt":"Fresh pineapple, juice, sweetened coconut cream and rum weighed in grams: two proposed servings with measured crushed ice.","summary":"A proposed blended piña colada with fresh pineapple, juice, sweetened coconut cream, white rum and measured ice. It makes 2 proposed servings with 15 minutes preparation and no cooking. It contains alcohol; quantities, texture and yield await kitchen testing. Nutrition includes the rum's energy and excludes garnishes.","category":"Drinks","category_slug":"bebidas","difficulty":"Easy","course":"Drink","cuisine":"Puerto Rican inspiration","prep_time_minutes":15,"cook_time_minutes":0,"total_time_minutes":15,"servings":2,"ingredients":[{"name":"fresh pineapple flesh, peeled, eyes and tough core removed","amount":"120","unit":"g","group":"Fruit"},{"name":"packaged pineapple juice with no added sugar, not undiluted concentrate","amount":"180","unit":"g","group":"Fruit"},{"name":"sweetened coconut cocktail cream, not coconut milk or unsweetened natural cream","amount":"60","unit":"g","group":"Coconut base"},{"name":"white rum at 40 % ABV, equivalent to 80 proof; weighed, not measured in milliliters","amount":"60","unit":"g","group":"Contains alcohol"},{"name":"crushed ice made from drinking water","amount":"180","unit":"g","group":"Chilling"}],"steps":[{"title":"Gather and weigh the ingredients","content":"Prepare a scale, clean board and knife, a blender suitable for crushed ice and two clean glasses with enough capacity. Measure 180 g packaged pineapple juice with no added sugar, 60 g sweetened coconut cocktail cream, 60 g white rum at 40 % ABV and 180 g crushed drinking-water ice. Set aside enough pineapple to obtain 120 g clean flesh later. Rum is weighed in grams: 60 g is not described as 60 ml. Use intact, in-date packages. Do not add sugar, syrup, milk, dairy cream, lime or garnishes outside this formula. Follow the blender instructions and do not use ice in a machine not designed for it.","image_url":"/recetas/receta-de-pina-colada/paso-01.webp","image_alt":"Pineapple, juice, sweetened coconut cream, rum and crushed ice beside an empty blender"},{"title":"Wash and cut the pineapple","content":"Wash the pineapple under drinking water before peeling, without soap or detergent, and dry the outside with clean material. Remove peel, eyes and tough core on a stable board; discard damaged areas and do not use rotten fruit. Weigh 120 g edible flesh and cut into pieces about 2 cm across. This amount excludes peel and core and all goes into the drink; do not reserve a garnish slice. Keep board, knife and hands clean and separate from raw meat. Use packaged ready-to-drink juice, not undiluted concentrate.","image_url":"/recetas/receta-de-pina-colada/paso-02.webp","image_alt":"Clean hands cutting peeled pineapple on a stable board, peel kept aside"},{"title":"Blend the fruit with coconut cream and juice","content":"Stir the sweetened coconut cream with a clean spoon if separated; do not confuse it with coconut milk or unsweetened cream. With the blender stopped, put the 180 g juice, 60 g coconut cream and 120 g pineapple into the jar. Close the lid and blend for about 30–45 seconds until no large fruit pieces remain. Stop and unplug before opening to scrape down; never insert hands or utensils near moving blades. Do not add rum or ice yet. Do not strain the fruit, since all the pulp is included in the nutrition.","image_url":"/recetas/receta-de-pina-colada/paso-03.webp","image_alt":"Fruit, juice and coconut cream in a stopped blender before adding rum and ice"},{"title":"Add rum and ice and finish blending","content":"Stop and unplug before opening. Add the measured 60 g white rum and 180 g crushed ice, without extra ice or water. Close the lid firmly and blend for about 30–60 seconds, observing manufacturer-required pauses, until uniformly cold with a fine slushy texture. Never insert a spoon while blending or overload the jar. Add actual time for extra pauses or another batch. Blending does not remove alcohol; this version contains it and is not described as alcohol-free.","image_url":"/recetas/receta-de-pina-colada/paso-04.webp","image_alt":"Closed blender with fruit-coconut mixture and crushed ice before final blending"},{"title":"Divide without adding garnishes","content":"Stop and unplug the blender. With a clean spoon away from a running machine, check for large fruit or ice pieces; if present, close the lid again and blend as needed. Divide all the mixture between 2 glasses of at least 350 ml capacity, alternating small pours to distribute pulp and ice similarly. Each proposed serving is approximately half the batch, not a verified final weight or volume. Pineapple slices, cherries, whipped cream, sugar and serving ice are not included in this formula's nutrition. Foam or slight separation does not prove failure or guarantee a tested texture.","image_url":"/recetas/receta-de-pina-colada/paso-05.webp","image_alt":"Stopped detached blender jar pouring the drink into one of two clear glasses"},{"title":"Serve promptly and record actual times","content":"Serve the 2 portions immediately with clean utensils. The proposal estimates 15 minutes preparation, 0 cooking and 15 minutes total, including washing, cutting, weighing, blending and pouring; add actual extra pauses or batches. No resting or kitchen test is claimed. If not consumed promptly, store covered at 4 °C or below and use within 1 day; melting ice and separating coconut cream change the texture and require remixing. Refrigerate within 2 hours out of cold storage, or 1 hour above 32 °C ambient temperature. Alcohol does not replace hygiene or make this a shelf-stable preserve. Clearly identify the rum version.","image_url":"/recetas/receta-de-pina-colada/portada.webp","image_alt":"Two glasses of pale yellow piña colada without garnishes or whipped cream"}],"notes":"Proposed blended piña colada with fruit, juice, sweetened coconut cream and rum, not an exact reproduction of IBA proportions or a tested recipe. Contains alcohol and is identified as an adult drink; blending and refrigeration do not remove it. Prepare and label any rum-free variant separately, define its quantities and recalculate rather than reusing these figures. Sweetened cocktail coconut cream is different from coconut milk and natural cream: check labels, allergens and added dairy ingredients for each brand. Ice must come from drinking water and the blender must be designed for it. Stop and unplug before opening or scraping near blades. Wash pineapple before peeling and keep equipment separate from raw meat. Serve promptly; refrigerate covered leftovers at 4 °C or below and use within 1 day, with texture loss. Refrigerate within 2 hours out of cold storage or 1 hour above 32 °C. Rum does not make the drink shelf-stable. Record and recalculate changes to cream, juice, rum or ice; calculate garnishes separately. Two servings and 15 minutes are untested proposals.","nutrition":{"calories":254.1,"protein_g":1.0,"carbs_g":35.4,"fat_g":5.1,"saturated_fat_g":4.7,"sodium_mg":13.5,"fiber_g":1.1,"sugar_g":30.3,"alcohol_g":10.0,"estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"piña fresca,120 g netos sin piel ni centro duro","edible_grams":120,"fdc_id":169124,"fdc_description":"Pineapple, raw, all varieties","per_100g":{"protein_g":0.54,"sodium_mg":1.0,"sugar_g":9.85,"fat_g":0.12,"fiber_g":1.4,"saturated_fat_g":0.009,"carbs_g":13.1,"calories":50.0,"alcohol_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/169124/nutrients"},{"ingredient":"zumo de piña envasado sin azúcar añadido, sin concentrar","edible_grams":180,"fdc_id":169947,"fdc_description":"Pineapple juice, canned or bottled, unsweetened, without added ascorbic acid","per_100g":{"saturated_fat_g":0.008,"carbs_g":12.9,"calories":53.0,"alcohol_g":0.0,"fat_g":0.12,"sugar_g":9.98,"fiber_g":0.2,"sodium_mg":2.0,"protein_g":0.36},"source_url":"https://fdc.nal.usda.gov/food-details/169947/nutrients"},{"ingredient":"crema de coco enlatada ENDULZADA para cócteles","edible_grams":60,"fdc_id":170171,"fdc_description":"Nuts, coconut cream, canned, sweetened","per_100g":{"alcohol_g":0.0,"saturated_fat_g":15.5,"fiber_g":0.2,"protein_g":1.17,"sodium_mg":36.0,"sugar_g":51.5,"fat_g":16.3,"carbs_g":53.2,"calories":357},"source_url":"https://fdc.nal.usda.gov/food-details/170171/nutrients"},{"ingredient":"ron blanco80proof/40%vol,60g pesados","edible_grams":60,"fdc_id":174817,"fdc_description":"Alcoholic beverage, distilled, rum, 80 proof","per_100g":{"fiber_g":0.0,"sodium_mg":1.0,"protein_g":0.0,"alcohol_g":33.4,"saturated_fat_g":0.0,"fat_g":0.0,"carbs_g":0.0,"calories":231,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/174817/nutrients"}],"serving_size":"Half the batch; 2 proposed servings","method":"Four verified USDA entries: edible grams multiplied by nutrients per 100 g, summed and divided by 2. Fresh pineapple FDC 169124, unsweetened packaged juice FDC 169947, SWEETENED coconut cream FDC 170171 and 80-proof rum FDC 174817. Uses USDA energy including alcohol, not only protein, fat and carbohydrate energy. The 180 g drinking-water ice contributes none of these fields.","note":"Estimate, not analysis or confirmed yield. All rum is included without modeled evaporation or removal by blending. Estimated alcohol is 10.0 g per serving from the rum entry, not measured final ABV or a safe-consumption claim. Sweetened coconut cream differs from natural cream or milk; brand, sugar, strength and quantities affect figures. All pulp retained without straining. Ice 180 g is included only in the 600 g initial ingredient sum, not a measured final volume or verified 300 g served portion. Excludes garnishes and accompaniments; all fields present, no missing data replaced by zero."},"keywords":["piña colada with rum","blended piña colada","sweetened coconut cream","pineapple cocktail"],"image_url":"/recetas/receta-de-pina-colada/portada.webp","gallery":["/recetas/receta-de-pina-colada/paso-01.webp","/recetas/receta-de-pina-colada/paso-02.webp","/recetas/receta-de-pina-colada/paso-03.webp","/recetas/receta-de-pina-colada/paso-04.webp","/recetas/receta-de-pina-colada/paso-05.webp"],"seo":{"title":"Piña colada with rum: quantities and blending steps","description":"Blend fresh pineapple, juice, sweetened coconut cream, white rum and measured ice. Two proposed servings with clear steps and nutrition including alcohol.","image_alt":"Two clear glasses of pale yellow creamy slushy piña colada without fruit garnish, cherries or added whipped cream","image_variants":["/recetas/receta-de-pina-colada/portada-1x1.webp","/recetas/receta-de-pina-colada/portada-4x3.webp","/recetas/receta-de-pina-colada/portada-16x9.webp"],"faq":[{"q":"Is sweetened coconut cream the same as coconut milk?","a":"No. This formula uses 60 g sweetened cocktail coconut cream with a specific USDA entry. Coconut milk, unsweetened cream and dairy cream change sugar, fat, flavor and texture; do not substitute while retaining the same figures."},{"q":"Can I make an alcohol-free version?","a":"Yes, as a separate variant: omit rum, define and record any replacement liquid and recalculate. Do not add rum to that variant or describe a blended rum drink as alcohol-free; blending does not remove alcohol. These calories do not apply to the other formula."},{"q":"Why does it get thinner while standing?","a":"Ice melts and coconut cream may separate. Serve freshly blended and do not add water or ice without recording it. The batch uses 180 g ice; changes affect dilution and serving weight. Identical texture across blenders and brands is not promised."}]},"published":true,"editorial_status":"published","content_html":"<p>A proposed blended piña colada with fresh pineapple, juice, sweetened coconut cream, white rum and measured ice. It makes 2 proposed servings with 15 minutes preparation and no cooking. It contains alcohol; quantities, texture and yield await kitchen testing. Nutrition includes the rum&#x27;s energy and excludes garnishes.</p><p>Proposed blended piña colada with fruit, juice, sweetened coconut cream and rum, not an exact reproduction of IBA proportions or a tested recipe. Contains alcohol and is identified as an adult drink; blending and refrigeration do not remove it. Prepare and label any rum-free variant separately, define its quantities and recalculate rather than reusing these figures. Sweetened cocktail coconut cream is different from coconut milk and natural cream: check labels, allergens and added dairy ingredients for each brand. Ice must come from drinking water and the blender must be designed for it. Stop and unplug before opening or scraping near blades. Wash pineapple before peeling and keep equipment separate from raw meat. Serve promptly; refrigerate covered leftovers at 4 °C or below and use within 1 day, with texture loss. Refrigerate within 2 hours out of cold storage or 1 hour above 32 °C. Rum does not make the drink shelf-stable. Record and recalculate changes to cream, juice, rum or ice; calculate garnishes separately. Two servings and 15 minutes are untested proposals.</p>"},{"id":"3863e0f7-ba1c-5fb7-8a3c-ae91d006a813","recipe_group_id":"e91765d0-3d25-4790-a08f-89ce82446332","slug":"recette-pina-colada","public_path":"/fr/recette-pina-colada","source_url":"https://manualdecocina.com/fr/recette-pina-colada/","language":"fr","title":"Piña colada mixée au rhum et à la crème de coco","excerpt":"Ananas frais, jus, crème de coco sucrée et rhum pesés en grammes : deux portions proposées avec glace pilée mesurée.","summary":"Proposition de piña colada mixée avec ananas frais, jus, crème de coco sucrée, rhum blanc et glace mesurée. Elle prévoit 2 portions et 15 minutes de préparation sans cuisson. Elle contient de l'alcool ; quantités, texture et rendement restent à tester en cuisine. La nutrition inclut l'énergie du rhum et exclut les décorations.","category":"Boissons","category_slug":"bebidas","difficulty":"Facile","course":"Boisson","cuisine":"Inspiration portoricaine","prep_time_minutes":15,"cook_time_minutes":0,"total_time_minutes":15,"servings":2,"ingredients":[{"name":"ananas frais, chair sans peau, yeux ni cœur dur","amount":"120","unit":"g","group":"Fruit"},{"name":"jus d'ananas conditionné sans sucre ajouté, pas de concentré non dilué","amount":"180","unit":"g","group":"Fruit"},{"name":"crème de coco sucrée pour cocktails, pas de lait de coco ni crème naturelle non sucrée","amount":"60","unit":"g","group":"Base coco"},{"name":"rhum blanc à 40 % vol., soit 80 proof ; quantité pesée, pas en millilitres","amount":"60","unit":"g","group":"Avec alcool"},{"name":"glace pilée faite avec de l'eau potable","amount":"180","unit":"g","group":"Froid"}],"steps":[{"title":"Rassembler et peser les ingrédients","content":"Préparez une balance, une planche et un couteau propres, un blender adapté à la glace pilée et deux verres propres assez grands. Mesurez 180 g de jus d'ananas conditionné sans sucre ajouté, 60 g de crème de coco sucrée pour cocktails, 60 g de rhum blanc à 40 % vol. et 180 g de glace pilée d'eau potable. Prévoyez l'ananas pour obtenir ensuite 120 g de chair propre. Le rhum est pesé en grammes : 60 g ne sont pas présentés comme 60 ml. Utilisez des emballages intacts et dans leur date. N'ajoutez pas de sucre, sirop, lait, crème laitière, citron vert ni décoration hors de la formule. Suivez la notice du blender et n'utilisez pas de glace dans un appareil qui n'est pas conçu pour cela.","image_url":"/recetas/receta-de-pina-colada/paso-01.webp","image_alt":"Ananas, jus, crème de coco sucrée, rhum et glace pilée près d'un blender vide"},{"title":"Laver et couper l'ananas","content":"Lavez l'ananas à l'eau potable avant de l'éplucher, sans savon ni détergent, puis séchez l'extérieur avec du matériel propre. Retirez peau, yeux et cœur dur sur une planche stable ; éliminez les parties abîmées et n'utilisez pas de fruit pourri. Pesez 120 g de chair comestible et coupez en dés d'environ 2 cm. Cette quantité exclut peau et cœur et va entièrement dans la boisson, sans réserver de tranche décorative. Gardez planche, couteau et mains propres, séparés des viandes crues. Le jus doit être conditionné et prêt à boire, pas un concentré non dilué.","image_url":"/recetas/receta-de-pina-colada/paso-02.webp","image_alt":"Mains propres coupant l'ananas épluché sur planche stable, peau séparée"},{"title":"Mixer le fruit avec le coco et le jus","content":"Remuez la crème de coco sucrée avec une cuillère propre si elle est séparée ; ne la confondez pas avec du lait de coco ou de la crème non sucrée. Blender arrêté, mettez les 180 g de jus, 60 g de crème de coco et 120 g d'ananas dans le bol. Fermez et mixez environ 30–45 secondes jusqu'à disparition des gros morceaux. Arrêtez et débranchez avant d'ouvrir pour racler ; n'approchez jamais mains ou ustensiles des lames en mouvement. N'ajoutez pas encore rhum ou glace. Ne filtrez pas le fruit : toute la pulpe est incluse dans la nutrition.","image_url":"/recetas/receta-de-pina-colada/paso-03.webp","image_alt":"Fruit, jus et crème de coco dans le blender arrêté avant rhum et glace"},{"title":"Ajouter rhum et glace puis finir de mixer","content":"Arrêtez et débranchez avant d'ouvrir. Ajoutez les 60 g de rhum blanc et les 180 g de glace pilée mesurés, sans glace ni eau supplémentaires. Fermez fermement et mixez environ 30–60 secondes, avec les pauses prescrites par le fabricant, pour une boisson uniforme et froide à texture de granité fin. N'introduisez pas de cuillère pendant le fonctionnement et ne surchargez pas le bol. Comptez le temps réel des pauses supplémentaires ou d'une autre tournée. Le mixage n'élimine pas l'alcool : cette version en contient et n'est pas présentée comme sans alcool.","image_url":"/recetas/receta-de-pina-colada/paso-04.webp","image_alt":"Blender fermé avec mélange ananas-coco et glace pilée"},{"title":"Répartir sans décoration supplémentaire","content":"Arrêtez et débranchez le blender. Vérifiez avec une cuillère propre, hors de l'appareil en marche, l'absence de gros morceaux de fruit ou de glace ; sinon, refermez et mixez autant que nécessaire. Répartissez toute la préparation dans 2 verres d'au moins 350 ml de capacité, en alternant de petites quantités pour distribuer pulpe et glace de façon semblable. Chaque portion proposée vaut environ la moitié du lot, sans poids ni volume final vérifiés. Tranches d'ananas, cerises, chantilly, sucre et glace de service ne sont pas compris dans la nutrition. Mousse ou légère séparation ne prouvent pas un échec et ne garantissent pas une texture testée.","image_url":"/recetas/receta-de-pina-colada/paso-05.webp","image_alt":"Bol détaché du blender arrêté versant dans un des deux verres"},{"title":"Servir immédiatement et noter les durées réelles","content":"Servez les 2 portions aussitôt avec des ustensiles propres. La proposition estime 15 minutes de préparation, 0 de cuisson et 15 minutes au total, comprenant lavage, découpe, pesée, mixage et répartition ; ajoutez toute pause ou tournée supplémentaire réelle. Aucun repos ni essai en cuisine n'est revendiqué. Si la boisson n'est pas consommée rapidement, conservez couverte à 4 °C ou moins et utilisez dans un délai de 1 jour ; fonte de la glace et séparation du coco changent la texture et nécessitent de mélanger à nouveau. Réfrigérez dans les 2 heures hors du froid, ou dans 1 heure si l'ambiance dépasse 32 °C. L'alcool ne remplace pas l'hygiène et n'en fait pas une conserve stable. Identifiez clairement la version au rhum.","image_url":"/recetas/receta-de-pina-colada/portada.webp","image_alt":"Deux verres de piña colada jaune pâle sans décoration ni chantilly"}],"notes":"Proposition mixée avec fruit, jus, crème de coco sucrée et rhum, sans reproduire exactement les proportions IBA ni revendiquer un essai. Contient de l'alcool et est identifiée comme boisson pour adultes ; mixage et froid ne l'éliminent pas. Préparez et étiquetez séparément une variante sans rhum, fixez ses quantités et recalculez sans réutiliser ces valeurs. La crème de coco sucrée pour cocktails diffère du lait et de la crème naturelle : vérifiez emballages, allergènes et éventuels produits laitiers ajoutés. Glace d'eau potable et blender adapté sont nécessaires. Arrêtez et débranchez avant d'ouvrir ou de racler près des lames. Lavez l'ananas avant d'éplucher et séparez le matériel des viandes crues. Servez aussitôt ; couvrez les restes à 4 °C ou moins et consommez dans 1 jour, avec perte de texture. Réfrigérez dans les 2 heures hors du froid, ou 1 heure au-dessus de 32 °C. Le rhum ne rend pas la boisson stable à température ambiante. Notez et recalculez tout changement de crème, jus, rhum ou glace ; décorations à part. Deux portions et 15 minutes sont des propositions non testées.","nutrition":{"calories":254.1,"protein_g":1.0,"carbs_g":35.4,"fat_g":5.1,"saturated_fat_g":4.7,"sodium_mg":13.5,"fiber_g":1.1,"sugar_g":30.3,"alcohol_g":10.0,"estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"piña fresca,120 g netos sin piel ni centro duro","edible_grams":120,"fdc_id":169124,"fdc_description":"Pineapple, raw, all varieties","per_100g":{"protein_g":0.54,"sodium_mg":1.0,"sugar_g":9.85,"fat_g":0.12,"fiber_g":1.4,"saturated_fat_g":0.009,"carbs_g":13.1,"calories":50.0,"alcohol_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/169124/nutrients"},{"ingredient":"zumo de piña envasado sin azúcar añadido, sin concentrar","edible_grams":180,"fdc_id":169947,"fdc_description":"Pineapple juice, canned or bottled, unsweetened, without added ascorbic acid","per_100g":{"saturated_fat_g":0.008,"carbs_g":12.9,"calories":53.0,"alcohol_g":0.0,"fat_g":0.12,"sugar_g":9.98,"fiber_g":0.2,"sodium_mg":2.0,"protein_g":0.36},"source_url":"https://fdc.nal.usda.gov/food-details/169947/nutrients"},{"ingredient":"crema de coco enlatada ENDULZADA para cócteles","edible_grams":60,"fdc_id":170171,"fdc_description":"Nuts, coconut cream, canned, sweetened","per_100g":{"alcohol_g":0.0,"saturated_fat_g":15.5,"fiber_g":0.2,"protein_g":1.17,"sodium_mg":36.0,"sugar_g":51.5,"fat_g":16.3,"carbs_g":53.2,"calories":357},"source_url":"https://fdc.nal.usda.gov/food-details/170171/nutrients"},{"ingredient":"ron blanco80proof/40%vol,60g pesados","edible_grams":60,"fdc_id":174817,"fdc_description":"Alcoholic beverage, distilled, rum, 80 proof","per_100g":{"fiber_g":0.0,"sodium_mg":1.0,"protein_g":0.0,"alcohol_g":33.4,"saturated_fat_g":0.0,"fat_g":0.0,"carbs_g":0.0,"calories":231,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/174817/nutrients"}],"serving_size":"La moitié du lot ; 2 portions proposées","method":"Quatre fiches USDA vérifiées : grammes comestibles multipliés par nutriments pour 100 g, additionnés et divisés par 2. Ananas frais FDC 169124, jus conditionné sans sucre ajouté FDC 169947, crème de coco SUCRÉE FDC 170171 et rhum 80 proof FDC 174817. L'énergie USDA inclut l'alcool, pas seulement protéines, lipides et glucides. Glace d'eau potable 180 g sans contribution à ces champs.","note":"Estimation, pas analyse ni rendement confirmé. Tout le rhum est inclus, sans évaporation ni élimination supposée par mixage. Alcool estimé 10,0 g par portion d'après la fiche du rhum, pas une mesure de degré final ni une promesse de consommation sûre. Crème sucrée différente du lait ou de la crème naturelle ; marque, sucre, degré et quantités changent les chiffres. Pulpe entière non filtrée. Glace 180 g incluse seulement dans le poids initial de 600 g, pas dans un volume final mesuré ni une portion servie de 300 g vérifiée. Sans décoration ni accompagnement ; toutes les données présentes, absences jamais remplacées par zéro."},"keywords":["piña colada au rhum","piña colada mixée","crème de coco sucrée","cocktail à l'ananas"],"image_url":"/recetas/receta-de-pina-colada/portada.webp","gallery":["/recetas/receta-de-pina-colada/paso-01.webp","/recetas/receta-de-pina-colada/paso-02.webp","/recetas/receta-de-pina-colada/paso-03.webp","/recetas/receta-de-pina-colada/paso-04.webp","/recetas/receta-de-pina-colada/paso-05.webp"],"seo":{"title":"Piña colada au rhum : quantités et étapes de mixage","description":"Mixez ananas frais, jus, crème de coco sucrée, rhum blanc et glace mesurée. Deux portions proposées, étapes détaillées et nutrition incluant l'alcool.","image_alt":"Deux verres transparents de piña colada jaune pâle, crémeuse et glacée, sans tranches d'ananas, cerises ni chantilly ajoutée","image_variants":["/recetas/receta-de-pina-colada/portada-1x1.webp","/recetas/receta-de-pina-colada/portada-4x3.webp","/recetas/receta-de-pina-colada/portada-16x9.webp"],"faq":[{"q":"La crème de coco sucrée équivaut-elle au lait de coco ?","a":"Non. La formule emploie 60 g de crème de coco sucrée pour cocktails avec une fiche USDA spécifique. Lait de coco, crème non sucrée et crème laitière changent sucre, gras, goût et texture ; ne conservez pas les mêmes valeurs après substitution."},{"q":"Puis-je préparer une version sans alcool ?","a":"Oui, comme variante séparée : omettez le rhum, définissez et notez le liquide de remplacement éventuel, puis recalculez. N'ajoutez pas de rhum à cette variante et ne déclarez pas sans alcool une boisson au rhum après mixage : il n'est pas éliminé. Ces calories ne s'appliquent pas à l'autre formule."},{"q":"Pourquoi devient-elle plus liquide en attendant ?","a":"La glace fond et le coco peut se séparer. Servez fraîchement mixée et notez toute eau ou glace supplémentaire. Le lot prévoit 180 g de glace ; les changements affectent dilution et poids des portions. Une texture identique entre marques et appareils n'est pas promise."}]},"published":true,"editorial_status":"published","content_html":"<p>Proposition de piña colada mixée avec ananas frais, jus, crème de coco sucrée, rhum blanc et glace mesurée. Elle prévoit 2 portions et 15 minutes de préparation sans cuisson. Elle contient de l&#x27;alcool ; quantités, texture et rendement restent à tester en cuisine. La nutrition inclut l&#x27;énergie du rhum et exclut les décorations.</p><p>Proposition mixée avec fruit, jus, crème de coco sucrée et rhum, sans reproduire exactement les proportions IBA ni revendiquer un essai. Contient de l&#x27;alcool et est identifiée comme boisson pour adultes ; mixage et froid ne l&#x27;éliminent pas. Préparez et étiquetez séparément une variante sans rhum, fixez ses quantités et recalculez sans réutiliser ces valeurs. La crème de coco sucrée pour cocktails diffère du lait et de la crème naturelle : vérifiez emballages, allergènes et éventuels produits laitiers ajoutés. Glace d&#x27;eau potable et blender adapté sont nécessaires. Arrêtez et débranchez avant d&#x27;ouvrir ou de racler près des lames. Lavez l&#x27;ananas avant d&#x27;éplucher et séparez le matériel des viandes crues. Servez aussitôt ; couvrez les restes à 4 °C ou moins et consommez dans 1 jour, avec perte de texture. Réfrigérez dans les 2 heures hors du froid, ou 1 heure au-dessus de 32 °C. Le rhum ne rend pas la boisson stable à température ambiante. Notez et recalculez tout changement de crème, jus, rhum ou glace ; décorations à part. Deux portions et 15 minutes sont des propositions non testées.</p>"},{"id":"3251b3ad-ac9f-5e3a-b5ab-049f7df904e0","recipe_group_id":"e91765d0-3d25-4790-a08f-89ce82446332","slug":"ricetta-della-pina-colada","public_path":"/it/ricetta-della-pina-colada","source_url":"https://manualdecocina.com/it/ricetta-della-pina-colada/","language":"it","title":"Piña colada frullata con rum e crema di cocco","excerpt":"Ananas fresco, succo, crema di cocco zuccherata e rum pesati in grammi: due porzioni proposte con ghiaccio tritato misurato.","summary":"Proposta di piña colada frullata con ananas fresco, succo, crema di cocco zuccherata, rum bianco e ghiaccio misurato. Prevede 2 porzioni e 15 minuti di preparazione senza cottura. Contiene alcol; dosi, consistenza e resa attendono prova in cucina. La nutrizione include l'energia del rum ed esclude le guarnizioni.","category":"Bevande","category_slug":"bebidas","difficulty":"Facile","course":"Bevanda","cuisine":"Ispirazione portoricana","prep_time_minutes":15,"cook_time_minutes":0,"total_time_minutes":15,"servings":2,"ingredients":[{"name":"ananas fresco, polpa senza buccia, occhi e torsolo duro","amount":"120","unit":"g","group":"Frutta"},{"name":"succo d'ananas confezionato senza zucchero aggiunto, non concentrato non diluito","amount":"180","unit":"g","group":"Frutta"},{"name":"crema di cocco zuccherata per cocktail, non latte di cocco né crema naturale non zuccherata","amount":"60","unit":"g","group":"Base di cocco"},{"name":"rum bianco al 40 % vol., equivalente a 80 proof; pesato, non misurato in millilitri","amount":"60","unit":"g","group":"Con alcol"},{"name":"ghiaccio tritato prodotto con acqua potabile","amount":"180","unit":"g","group":"Freddo"}],"steps":[{"title":"Riunisci e pesa gli ingredienti","content":"Prepara bilancia, tagliere e coltello puliti, un frullatore adatto al ghiaccio tritato e due bicchieri puliti abbastanza capienti. Misura 180 g di succo d'ananas confezionato senza zucchero aggiunto, 60 g di crema di cocco zuccherata per cocktail, 60 g di rum bianco al 40 % vol. e 180 g di ghiaccio tritato di acqua potabile. Prevedi ananas sufficiente per ottenere poi 120 g di polpa pulita. Il rum si pesa in grammi: 60 g non vengono indicati come 60 ml. Usa confezioni integre e nei termini. Non aggiungere zucchero, sciroppo, latte, panna, lime o decorazioni fuori da questa formula. Segui le istruzioni e non usare ghiaccio se il frullatore non è progettato per triturarlo.","image_url":"/recetas/receta-de-pina-colada/paso-01.webp","image_alt":"Ananas, succo, crema di cocco zuccherata, rum e ghiaccio tritato accanto al frullatore vuoto"},{"title":"Lava e taglia l'ananas","content":"Lava l'ananas sotto acqua potabile prima di sbucciarlo, senza sapone o detergente, e asciuga l'esterno con materiale pulito. Su un tagliere stabile elimina buccia, occhi e torsolo duro; scarta parti danneggiate e non usare frutta marcia. Pesa 120 g di polpa edibile e taglia a cubetti di circa 2 cm. Il peso esclude buccia e torsolo e va interamente nella bevanda, senza tenere una fetta decorativa. Mantieni tagliere, coltello e mani puliti, separati dalla carne cruda. Il succo deve essere confezionato e pronto da bere, non un concentrato non diluito.","image_url":"/recetas/receta-de-pina-colada/paso-02.webp","image_alt":"Mani pulite tagliano ananas sbucciato su tagliere stabile, buccia separata"},{"title":"Frulla la frutta con cocco e succo","content":"Mescola la crema di cocco zuccherata con un cucchiaio pulito se è separata; non confonderla con latte di cocco o crema senza zucchero. A frullatore fermo inserisci i 180 g di succo, 60 g di crema di cocco e 120 g di ananas. Chiudi e frulla circa 30–45 secondi finché non restano pezzi grandi. Ferma e scollega prima di aprire per raschiare le pareti; non avvicinare mani o utensili alle lame in movimento. Non aggiungere ancora rum o ghiaccio. Non filtrare: tutta la polpa è inclusa nella nutrizione.","image_url":"/recetas/receta-de-pina-colada/paso-03.webp","image_alt":"Frutta, succo e crema nel frullatore fermo prima di rum e ghiaccio"},{"title":"Aggiungi rum e ghiaccio e termina di frullare","content":"Ferma e scollega prima di aprire. Aggiungi i 60 g di rum bianco e 180 g di ghiaccio tritato misurati, senza altro ghiaccio o acqua. Chiudi bene e frulla circa 30–60 secondi, rispettando le pause del produttore, fino a una bevanda fredda uniforme con consistenza di granita fine. Non inserire cucchiai mentre è in funzione e non sovraccaricare la caraffa. Conta il tempo reale di pause aggiuntive o di un altro ciclo. Frullare non elimina l'alcol: questa versione lo contiene e non è indicata come analcolica.","image_url":"/recetas/receta-de-pina-colada/paso-04.webp","image_alt":"Frullatore chiuso con miscela di ananas e cocco e ghiaccio tritato"},{"title":"Dividi senza aggiungere guarnizioni","content":"Ferma e scollega il frullatore. Con un cucchiaio pulito, lontano dall'apparecchio in funzione, controlla che non restino pezzi grandi di ghiaccio o frutta; se presenti, richiudi e frulla quanto necessario. Dividi tutta la miscela in 2 bicchieri da almeno 350 ml di capienza, versando piccole quantità alternate per distribuire polpa e ghiaccio in modo simile. Ogni porzione proposta è circa metà del lotto, non un peso o volume finale verificato. Fette d'ananas, ciliegie, panna, zucchero e ghiaccio di servizio sono esclusi dalla nutrizione. Schiuma o lieve separazione non dimostrano un errore né garantiscono una consistenza collaudata.","image_url":"/recetas/receta-de-pina-colada/paso-05.webp","image_alt":"Caraffa staccata del frullatore fermo versa in uno dei due bicchieri"},{"title":"Servi subito e registra i tempi reali","content":"Servi immediatamente le 2 porzioni con utensili puliti. Si stimano 15 minuti di preparazione, 0 di cottura e 15 minuti totali, compresi lavaggio, taglio, pesatura, frullatura e divisione; aggiungi pause o cicli supplementari effettivi. Non è previsto riposo né dichiarata una prova in cucina. Se non consumi subito, conserva coperto a 4 °C o meno e usa entro 1 giorno; scioglimento del ghiaccio e separazione del cocco cambiano la consistenza e richiedono di mescolare di nuovo. Refrigera entro 2 ore fuori dal freddo, o 1 ora se l'ambiente supera 32 °C. L'alcol non sostituisce l'igiene e non rende la bevanda una conserva stabile. Identifica chiaramente la versione con rum.","image_url":"/recetas/receta-de-pina-colada/portada.webp","image_alt":"Due bicchieri di piña colada giallo chiaro senza guarnizioni o panna"}],"notes":"Proposta frullata con frutta, succo, crema di cocco zuccherata e rum, non riproduzione esatta delle proporzioni IBA né ricetta provata. Contiene alcol ed è identificata come bevanda per adulti; frullare o refrigerare non lo elimina. Prepara ed etichetta separatamente una variante senza rum, definisci le quantità e ricalcola senza riutilizzare questi valori. Crema di cocco zuccherata per cocktail diversa da latte e crema naturale: controlla confezioni, allergeni ed eventuali latticini aggiunti. Ghiaccio di acqua potabile e frullatore idoneo sono necessari. Ferma e scollega prima di aprire o raschiare vicino alle lame. Lava l'ananas prima di pelare e separa utensili da carne cruda. Servi subito; avanzi coperti a 4 °C o meno, da usare entro 1 giorno con perdita di consistenza. Refrigera entro 2 ore fuori dal freddo o 1 ora sopra 32 °C. Il rum non conserva stabilmente la bevanda fuori dal frigo. Annota e ricalcola modifiche di crema, succo, rum o ghiaccio; guarnizioni a parte. Due porzioni e 15 minuti sono proposte non verificate.","nutrition":{"calories":254.1,"protein_g":1.0,"carbs_g":35.4,"fat_g":5.1,"saturated_fat_g":4.7,"sodium_mg":13.5,"fiber_g":1.1,"sugar_g":30.3,"alcohol_g":10.0,"estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"piña fresca,120 g netos sin piel ni centro duro","edible_grams":120,"fdc_id":169124,"fdc_description":"Pineapple, raw, all varieties","per_100g":{"protein_g":0.54,"sodium_mg":1.0,"sugar_g":9.85,"fat_g":0.12,"fiber_g":1.4,"saturated_fat_g":0.009,"carbs_g":13.1,"calories":50.0,"alcohol_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/169124/nutrients"},{"ingredient":"zumo de piña envasado sin azúcar añadido, sin concentrar","edible_grams":180,"fdc_id":169947,"fdc_description":"Pineapple juice, canned or bottled, unsweetened, without added ascorbic acid","per_100g":{"saturated_fat_g":0.008,"carbs_g":12.9,"calories":53.0,"alcohol_g":0.0,"fat_g":0.12,"sugar_g":9.98,"fiber_g":0.2,"sodium_mg":2.0,"protein_g":0.36},"source_url":"https://fdc.nal.usda.gov/food-details/169947/nutrients"},{"ingredient":"crema de coco enlatada ENDULZADA para cócteles","edible_grams":60,"fdc_id":170171,"fdc_description":"Nuts, coconut cream, canned, sweetened","per_100g":{"alcohol_g":0.0,"saturated_fat_g":15.5,"fiber_g":0.2,"protein_g":1.17,"sodium_mg":36.0,"sugar_g":51.5,"fat_g":16.3,"carbs_g":53.2,"calories":357},"source_url":"https://fdc.nal.usda.gov/food-details/170171/nutrients"},{"ingredient":"ron blanco80proof/40%vol,60g pesados","edible_grams":60,"fdc_id":174817,"fdc_description":"Alcoholic beverage, distilled, rum, 80 proof","per_100g":{"fiber_g":0.0,"sodium_mg":1.0,"protein_g":0.0,"alcohol_g":33.4,"saturated_fat_g":0.0,"fat_g":0.0,"carbs_g":0.0,"calories":231,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/174817/nutrients"}],"serving_size":"Metà del lotto; 2 porzioni proposte","method":"Quattro schede USDA verificate: grammi edibili moltiplicati per nutrienti per 100 g, sommati e divisi per 2. Ananas fresco FDC 169124, succo confezionato senza zucchero aggiunto FDC 169947, crema di cocco ZUCCHERATA FDC 170171 e rum 80 proof FDC 174817. Energia USDA comprensiva dell'alcol, non solo proteine, grassi e carboidrati. Ghiaccio di acqua potabile 180 g senza apporto in questi campi.","note":"Stima, non analisi né resa confermata. Tutto il rum incluso senza presumere evaporazione o eliminazione con frullatura. Alcol stimato 10,0 g per porzione dalla scheda del rum, non gradazione finale misurata o promessa di consumo sicuro. Crema zuccherata diversa da latte o crema naturale; marca, zucchero, gradazione e quantità cambiano i valori. Polpa intera non filtrata. Ghiaccio 180 g incluso solo nel peso iniziale di 600 g, non in volume finale misurato né porzione servita verificata di 300 g. Esclusi guarnizioni e accompagnamenti; dati presenti, mai sostituire assenze con zero."},"keywords":["piña colada con rum","piña colada frullata","crema di cocco zuccherata","cocktail all'ananas"],"image_url":"/recetas/receta-de-pina-colada/portada.webp","gallery":["/recetas/receta-de-pina-colada/paso-01.webp","/recetas/receta-de-pina-colada/paso-02.webp","/recetas/receta-de-pina-colada/paso-03.webp","/recetas/receta-de-pina-colada/paso-04.webp","/recetas/receta-de-pina-colada/paso-05.webp"],"seo":{"title":"Piña colada con rum: quantità e passaggi per frullare","description":"Ananas fresco, succo, crema di cocco zuccherata, rum bianco e ghiaccio misurato: due porzioni proposte, fasi chiare e nutrizione con alcol incluso.","image_alt":"Due bicchieri trasparenti di piña colada giallo pallido, cremosa e ghiacciata, senza fette d'ananas, ciliegie o panna aggiunta","image_variants":["/recetas/receta-de-pina-colada/portada-1x1.webp","/recetas/receta-de-pina-colada/portada-4x3.webp","/recetas/receta-de-pina-colada/portada-16x9.webp"],"faq":[{"q":"La crema di cocco zuccherata equivale al latte di cocco?","a":"No. Questa formula usa 60 g di crema di cocco zuccherata per cocktail con scheda USDA specifica. Latte di cocco, crema non zuccherata e panna cambiano zucchero, grasso, gusto e consistenza; non sostituire mantenendo le stesse cifre."},{"q":"Posso fare una versione analcolica?","a":"Sì, come variante separata: ometti il rum, definisci e annota l'eventuale liquido sostitutivo e ricalcola. Non aggiungere rum a quella variante né chiamare analcolica una bevanda con rum dopo averla frullata: l'alcol resta. Le calorie di questa formula non valgono per l'altra."},{"q":"Perché diventa più liquida aspettando?","a":"Il ghiaccio si scioglie e il cocco può separarsi. Servi appena frullata e registra acqua o ghiaccio extra. Sono previsti 180 g di ghiaccio nel lotto; modifiche cambiano diluizione e peso delle porzioni. Non si promette consistenza identica tra marche e frullatori."}]},"published":true,"editorial_status":"published","content_html":"<p>Proposta di piña colada frullata con ananas fresco, succo, crema di cocco zuccherata, rum bianco e ghiaccio misurato. Prevede 2 porzioni e 15 minuti di preparazione senza cottura. Contiene alcol; dosi, consistenza e resa attendono prova in cucina. La nutrizione include l&#x27;energia del rum ed esclude le guarnizioni.</p><p>Proposta frullata con frutta, succo, crema di cocco zuccherata e rum, non riproduzione esatta delle proporzioni IBA né ricetta provata. Contiene alcol ed è identificata come bevanda per adulti; frullare o refrigerare non lo elimina. Prepara ed etichetta separatamente una variante senza rum, definisci le quantità e ricalcola senza riutilizzare questi valori. Crema di cocco zuccherata per cocktail diversa da latte e crema naturale: controlla confezioni, allergeni ed eventuali latticini aggiunti. Ghiaccio di acqua potabile e frullatore idoneo sono necessari. Ferma e scollega prima di aprire o raschiare vicino alle lame. Lava l&#x27;ananas prima di pelare e separa utensili da carne cruda. Servi subito; avanzi coperti a 4 °C o meno, da usare entro 1 giorno con perdita di consistenza. Refrigera entro 2 ore fuori dal freddo o 1 ora sopra 32 °C. Il rum non conserva stabilmente la bevanda fuori dal frigo. Annota e ricalcola modifiche di crema, succo, rum o ghiaccio; guarnizioni a parte. Due porzioni e 15 minuti sono proposte non verificate.</p>"},{"id":"64f83dc0-12ab-5ecd-b89a-aca7cc75e5ec","recipe_group_id":"e91765d0-3d25-4790-a08f-89ce82446332","slug":"ピニャコラーダのレシピ","public_path":"/ja/ピニャコラーダのレシピ","source_url":"https://manualdecocina.com/ja/ピニャコラーダのレシピ/","language":"ja","title":"ラムとココナッツクリームのピニャコラーダ","excerpt":"生のパイナップル、ジュース、加糖ココナッツクリーム、ラムをグラムで計量。砕いた氷を使う二人分の提案です。","summary":"生パイナップル、ジュース、加糖ココナッツクリーム、ホワイトラム、計量した氷で作るピニャコラーダの案です。2人分、準備15分、加熱なしを提案します。アルコールを含み、分量、食感、出来上がり量は調理で未確認です。栄養にはラム由来のエネルギーを含め、飾りは含めません。","category":"飲み物","category_slug":"bebidas","difficulty":"簡単","course":"飲み物","cuisine":"プエルトリコ風","prep_time_minutes":15,"cook_time_minutes":0,"total_time_minutes":15,"servings":2,"ingredients":[{"name":"生パイナップル、皮、芽、硬い芯を除いた果肉","amount":"120","unit":"g","group":"果物"},{"name":"容器入りパイナップルジュース、砂糖無添加、そのまま飲めるもの（未希釈濃縮液は不可）","amount":"180","unit":"g","group":"果物"},{"name":"カクテル用加糖ココナッツクリーム（ココナッツミルクや無糖の天然クリームとは異なる）","amount":"60","unit":"g","group":"ココナッツベース"},{"name":"ホワイトラム、アルコール40 %、80 proof相当、ミリリットルではなく重量で計量","amount":"60","unit":"g","group":"アルコール入り"},{"name":"飲用水で作った砕いた氷","amount":"180","unit":"g","group":"冷却"}],"steps":[{"title":"材料をそろえて量る","content":"はかり、清潔なまな板と包丁、砕いた氷に対応したブレンダー、十分な容量の清潔なグラスを二つ用意します。砂糖無添加の容器入りパイナップルジュース180 g、カクテル用加糖ココナッツクリーム60 g、アルコール40 %のホワイトラム60 g、飲用水で作った砕いた氷180 gを量ります。後で清潔な果肉120 gを取れる量のパイナップルを用意してください。ラムはグラムで量り、60 gを60 mlとして扱いません。期限内で包装に破損のないものを使います。砂糖、シロップ、牛乳、生クリーム、ライム、指定外の飾りは加えません。機器の説明書に従い、氷を砕けない機器では氷を使わないでください。","image_url":"/recetas/receta-de-pina-colada/paso-01.webp","image_alt":"空のブレンダーと別々に量った果肉、ジュース、加糖ココナッツクリーム、ラム、砕いた氷"},{"title":"パイナップルを洗って切る","content":"皮をむく前にパイナップルを飲用水で洗い、石けんや洗剤は使わず、清潔なもので外側を乾かします。安定したまな板で皮、芽、硬い芯を除き、傷んだ部分を捨て、腐った果物は使いません。可食部120 gを量り、約2 cmの角切りにします。この量には皮や芯を含めず、果肉はすべて飲み物に使い、飾りの輪切りは取り分けません。まな板、包丁、手を清潔にし、生肉と分けます。ジュースは容器入りのそのまま飲めるものを使い、未希釈濃縮液は使いません。","image_url":"/recetas/receta-de-pina-colada/paso-02.webp","image_alt":"安定したまな板で皮を除いたパイナップルを切る清潔な手"},{"title":"果物、ココナッツ、ジュースを攪拌する","content":"加糖ココナッツクリームが分離していたら清潔なスプーンで混ぜます。ココナッツミルクや無糖クリームと混同しないでください。停止したブレンダーにジュース180 g、ココナッツクリーム60 g、パイナップル120 gを入れます。ふたを閉め、約30–45秒、大きな果肉がなくなるまで攪拌します。内壁をぬぐうために開ける前には停止してプラグを抜き、回転中の刃に手や器具を近づけません。ラムと氷はまだ入れません。果肉をすべて栄養に含めているため、こさずに使います。","image_url":"/recetas/receta-de-pina-colada/paso-03.webp","image_alt":"ラムと氷を加える前の果肉、ジュース、ココナッツクリーム"},{"title":"ラムと氷を加えて仕上げる","content":"停止してプラグを抜いてから開けます。計量したホワイトラム60 gと砕いた氷180 gを加え、余分な氷や水は足しません。ふたをしっかり閉め、メーカー指定の休止を挟みながら約30–60秒、均一で冷たく細かなシャーベット状になるまで攪拌します。運転中にスプーンを入れて補助せず、容器を入れ過ぎないでください。休止や追加の攪拌回が必要なら実際の時間を足します。攪拌でアルコールは取り除かれません。この配合はアルコールを含み、ノンアルコールとはしません。","image_url":"/recetas/receta-de-pina-colada/paso-04.webp","image_alt":"閉じたブレンダーに入った果物とココナッツの混合物と砕いた氷"},{"title":"飾りを加えず分ける","content":"ブレンダーを停止してプラグを抜きます。運転中の機器から離れた状態で、清潔なスプーンを使って大きな氷や果肉が残っていないか確認し、残っていれば再びふたをして必要な時間攪拌します。全量を容量350 ml以上のグラス2個に、小量ずつ交互に注いで果肉と氷を同じように分けます。一人分は全量の約半分という提案で、最終重量や容量を実測済みとはしません。パイナップルの輪切り、チェリー、生クリーム、砂糖、提供用の追加氷は栄養に含めません。泡や軽い分離は失敗の証明ではなく、検証済みの食感を保証するものでもありません。","image_url":"/recetas/receta-de-pina-colada/paso-05.webp","image_alt":"停止して取り外したブレンダー容器から二つのグラスの一方へ注ぐ工程"},{"title":"すぐ提供し、実際の時間を記録する","content":"清潔な器具を使い、2人分をすぐ提供します。洗浄、切り分け、計量、攪拌、注ぎ分けを含め、準備15分、加熱0分、合計15分を目安とし、実際の追加休止や攪拌回を足します。必須の休ませ時間や調理試験の実施は主張しません。すぐ飲まない場合はふたをして4 °C以下で保存し、1日以内に使用してください。氷が溶け、ココナッツが分離すると食感が変わり、混ぜ直す必要があります。冷蔵から出して2時間以内、室温が32 °Cを超える場合は1時間以内に冷蔵します。アルコールは衛生管理の代わりにならず、常温保存できる飲み物にはなりません。ラム入りと明確に表示してください。","image_url":"/recetas/receta-de-pina-colada/portada.webp","image_alt":"飾りや生クリームを加えていない淡黄色のピニャコラーダ二杯"}],"notes":"果物、ジュース、加糖ココナッツクリーム、ラムを攪拌する提案で、IBAの比率の完全な再現や試作済みレシピとはしません。アルコールを含み、大人向けの飲み物として表示します。攪拌や冷蔵でアルコールはなくなりません。ラムなしの別案は別に作って表示し、分量を決めて再計算し、この数値を使い回しません。カクテル用加糖ココナッツクリームはミルクや天然の無糖クリームと異なります。商品表示のアレルゲンや乳製品添加を確認してください。飲用水の氷と氷に対応したブレンダーを使います。開けたり刃の近くをぬぐったりする前に停止してプラグを抜きます。皮をむく前に果物を洗い、器具は生肉と分けます。作ってすぐ提供し、残りはふたをして4 °C以下で保存、1日以内に使いますが食感は変わります。冷蔵から出して2時間以内、室温32 °C超なら1時間以内に冷蔵します。ラムで常温保存が可能になるわけではありません。クリーム、ジュース、ラム、氷の変更を記録して再計算し、飾りも別に計算します。二人分と15分は未確認の提案です。","nutrition":{"calories":254.1,"protein_g":1.0,"carbs_g":35.4,"fat_g":5.1,"saturated_fat_g":4.7,"sodium_mg":13.5,"fiber_g":1.1,"sugar_g":30.3,"alcohol_g":10.0,"estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"piña fresca,120 g netos sin piel ni centro duro","edible_grams":120,"fdc_id":169124,"fdc_description":"Pineapple, raw, all varieties","per_100g":{"protein_g":0.54,"sodium_mg":1.0,"sugar_g":9.85,"fat_g":0.12,"fiber_g":1.4,"saturated_fat_g":0.009,"carbs_g":13.1,"calories":50.0,"alcohol_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/169124/nutrients"},{"ingredient":"zumo de piña envasado sin azúcar añadido, sin concentrar","edible_grams":180,"fdc_id":169947,"fdc_description":"Pineapple juice, canned or bottled, unsweetened, without added ascorbic acid","per_100g":{"saturated_fat_g":0.008,"carbs_g":12.9,"calories":53.0,"alcohol_g":0.0,"fat_g":0.12,"sugar_g":9.98,"fiber_g":0.2,"sodium_mg":2.0,"protein_g":0.36},"source_url":"https://fdc.nal.usda.gov/food-details/169947/nutrients"},{"ingredient":"crema de coco enlatada ENDULZADA para cócteles","edible_grams":60,"fdc_id":170171,"fdc_description":"Nuts, coconut cream, canned, sweetened","per_100g":{"alcohol_g":0.0,"saturated_fat_g":15.5,"fiber_g":0.2,"protein_g":1.17,"sodium_mg":36.0,"sugar_g":51.5,"fat_g":16.3,"carbs_g":53.2,"calories":357},"source_url":"https://fdc.nal.usda.gov/food-details/170171/nutrients"},{"ingredient":"ron blanco80proof/40%vol,60g pesados","edible_grams":60,"fdc_id":174817,"fdc_description":"Alcoholic beverage, distilled, rum, 80 proof","per_100g":{"fiber_g":0.0,"sodium_mg":1.0,"protein_g":0.0,"alcohol_g":33.4,"saturated_fat_g":0.0,"fat_g":0.0,"carbs_g":0.0,"calories":231,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/174817/nutrients"}],"serving_size":"全量の半分、2人分の提案","method":"確認した四件のUSDAデータで、可食部グラム数と100 g当たり栄養素を掛け合わせ、合計して2で割ります。生パイナップルFDC 169124、砂糖無添加の容器入りジュースFDC 169947、加糖ココナッツクリームFDC 170171、80 proofのラムFDC 174817。USDAのエネルギーにはアルコールを含み、たんぱく質、脂肪、炭水化物だけでは計算しません。飲用水の氷180 gはこれらの項目に寄与しません。","note":"推定値であり、分析結果や確認済みの出来上がり量ではありません。ラム全量を含め、攪拌による蒸発や除去を仮定しません。ラムのデータから一人分のアルコールは推定10.0 gですが、完成品の度数の実測値や安全な飲酒を示すものではありません。加糖クリームは天然クリームやミルクとは異なり、ブランド、糖、度数、量で数値は変わります。果肉はすべて使い、こしません。氷180 gは最初の材料合計600 gにだけ含め、最終容量や実測済みの一人分300 gを主張しません。飾りや付け合わせは除外し、全項目にデータがあり、欠測をゼロにしません。"},"keywords":["ラムのピニャコラーダ","ブレンダーのピニャコラーダ","加糖ココナッツクリーム","パイナップルカクテル"],"image_url":"/recetas/receta-de-pina-colada/portada.webp","gallery":["/recetas/receta-de-pina-colada/paso-01.webp","/recetas/receta-de-pina-colada/paso-02.webp","/recetas/receta-de-pina-colada/paso-03.webp","/recetas/receta-de-pina-colada/paso-04.webp","/recetas/receta-de-pina-colada/paso-05.webp"],"seo":{"title":"ラム入りピニャコラーダ：分量と攪拌の手順","description":"生パイナップル、ジュース、加糖ココナッツクリーム、ラム、計量した氷を使う二人分の案。手順とアルコールを含む栄養計算を説明。","image_alt":"透明なグラス二つの淡黄色でクリーミーなピニャコラーダ。果物の飾り、チェリー、生クリームはなし","image_variants":["/recetas/receta-de-pina-colada/portada-1x1.webp","/recetas/receta-de-pina-colada/portada-4x3.webp","/recetas/receta-de-pina-colada/portada-16x9.webp"],"faq":[{"q":"加糖ココナッツクリームはココナッツミルクと同じですか？","a":"違います。この配合は専用のUSDAデータに対応したカクテル用加糖ココナッツクリーム60 gを使います。ミルク、無糖クリーム、生クリームは糖、脂肪、味、食感を変えるため、置き換えて同じ数値を使わないでください。"},{"q":"ノンアルコール版は作れますか？","a":"別の案として作れます。ラムを省き、代わりの液体を使うなら分量を決めて記録し、再計算してください。その飲み物にラムを加えず、ラム入りを攪拌してノンアルコールと呼ばないでください。攪拌ではアルコールは消えません。この配合のカロリーを別案に当てはめません。"},{"q":"時間がたつと薄くなるのはなぜですか？","a":"氷が溶け、ココナッツが分離することがあります。作りたてを提供し、水や氷を足したら記録します。この配合の氷は全量で180 gです。変更すると希釈と一人分の重量が変わります。機器やブランドが違っても同じ食感になるとは約束しません。"}]},"published":true,"editorial_status":"published","content_html":"<p>生パイナップル、ジュース、加糖ココナッツクリーム、ホワイトラム、計量した氷で作るピニャコラーダの案です。2人分、準備15分、加熱なしを提案します。アルコールを含み、分量、食感、出来上がり量は調理で未確認です。栄養にはラム由来のエネルギーを含め、飾りは含めません。</p><p>果物、ジュース、加糖ココナッツクリーム、ラムを攪拌する提案で、IBAの比率の完全な再現や試作済みレシピとはしません。アルコールを含み、大人向けの飲み物として表示します。攪拌や冷蔵でアルコールはなくなりません。ラムなしの別案は別に作って表示し、分量を決めて再計算し、この数値を使い回しません。カクテル用加糖ココナッツクリームはミルクや天然の無糖クリームと異なります。商品表示のアレルゲンや乳製品添加を確認してください。飲用水の氷と氷に対応したブレンダーを使います。開けたり刃の近くをぬぐったりする前に停止してプラグを抜きます。皮をむく前に果物を洗い、器具は生肉と分けます。作ってすぐ提供し、残りはふたをして4 °C以下で保存、1日以内に使いますが食感は変わります。冷蔵から出して2時間以内、室温32 °C超なら1時間以内に冷蔵します。ラムで常温保存が可能になるわけではありません。クリーム、ジュース、ラム、氷の変更を記録して再計算し、飾りも別に計算します。二人分と15分は未確認の提案です。</p>"},{"id":"56a82069-5e7e-5c0b-9aea-5e71cdfb5c82","recipe_group_id":"e91765d0-3d25-4790-a08f-89ce82446332","slug":"receita-de-pina-colada","public_path":"/pt/receita-de-pina-colada","source_url":null,"language":"pt","title":"Piña colada batida com rum e creme de coco","excerpt":"Abacaxi fresco, suco, creme de coco adoçado e rum pesados em gramas: duas porções propostas com gelo triturado medido.","summary":"Proposta de piña colada batida com abacaxi fresco, suco, creme de coco adoçado, rum branco e gelo medido. Prevê 2 porções e 15 minutos de preparo, sem cozimento. Contém álcool; quantidades, textura e rendimento ainda precisam de teste na cozinha. A nutrição inclui a energia do rum e exclui enfeites.","category":"Bebidas","category_slug":"bebidas","difficulty":"Fácil","course":"Bebida","cuisine":"Inspiração porto-riquenha","prep_time_minutes":15,"cook_time_minutes":0,"total_time_minutes":15,"servings":2,"ingredients":[{"name":"abacaxi fresco, polpa sem casca, olhos ou miolo duro","amount":"120","unit":"g","group":"Fruta"},{"name":"suco de abacaxi embalado sem açúcar adicionado, não concentrado sem diluir","amount":"180","unit":"g","group":"Fruta"},{"name":"creme de coco adoçado para coquetéis, não leite de coco nem creme natural sem açúcar","amount":"60","unit":"g","group":"Base de coco"},{"name":"rum branco a 40 % vol., equivalente a 80 proof; quantidade pesada, não em mililitros","amount":"60","unit":"g","group":"Com álcool"},{"name":"gelo triturado feito com água potável","amount":"180","unit":"g","group":"Frio"}],"steps":[{"title":"Separe e pese os ingredientes","content":"Prepare balança, tábua e faca limpas, liquidificador próprio para gelo triturado e dois copos limpos com capacidade suficiente. Meça 180 g de suco de abacaxi embalado sem açúcar adicionado, 60 g de creme de coco adoçado para coquetéis, 60 g de rum branco a 40 % vol. e 180 g de gelo triturado de água potável. Separe abacaxi suficiente para obter depois 120 g de polpa limpa. O rum é pesado em gramas: 60 g não são apresentados como 60 ml. Use embalagens intactas e dentro da validade. Não acrescente açúcar, xarope, leite, creme de leite, limão nem enfeites fora da fórmula. Siga as instruções do liquidificador e não use gelo se ele não foi projetado para triturá-lo.","image_url":"/recetas/receta-de-pina-colada/paso-01.webp","image_alt":"Abacaxi, suco, creme de coco adoçado, rum e gelo triturado junto ao liquidificador vazio"},{"title":"Lave e corte o abacaxi","content":"Lave o abacaxi sob água potável antes de descascar, sem sabão nem detergente, e seque o exterior com material limpo. Retire casca, olhos e miolo duro sobre uma tábua estável; descarte áreas danificadas e não use fruta podre. Pese 120 g de polpa comestível e corte em cubos de cerca de 2 cm. A quantidade não inclui casca nem miolo e entra toda na bebida, sem reservar fatia para enfeitar. Mantenha tábua, faca e mãos limpas, separadas de carnes cruas. Use suco embalado pronto para beber, não concentrado sem diluir.","image_url":"/recetas/receta-de-pina-colada/paso-02.webp","image_alt":"Mãos limpas cortando abacaxi descascado sobre tábua estável, casca separada"},{"title":"Bata a fruta com coco e suco","content":"Mexa o creme de coco adoçado com colher limpa se houver separação; não confunda com leite de coco ou creme sem açúcar. Com o liquidificador parado, coloque os 180 g de suco, 60 g de creme de coco e 120 g de abacaxi no copo. Tampe e bata por cerca de 30–45 segundos até não restarem pedaços grandes. Pare e tire da tomada antes de abrir para raspar; não aproxime mãos ou utensílios de lâminas em movimento. Ainda não acrescente rum nem gelo. Não coe a fruta, pois toda a polpa entra no cálculo nutricional.","image_url":"/recetas/receta-de-pina-colada/paso-03.webp","image_alt":"Fruta, suco e creme no liquidificador parado antes de rum e gelo"},{"title":"Acrescente rum e gelo e termine de bater","content":"Pare e tire da tomada antes de abrir. Acrescente os 60 g de rum branco e 180 g de gelo triturado medidos, sem mais gelo ou água. Feche bem a tampa e bata por cerca de 30–60 segundos, com as pausas indicadas pelo fabricante, até a bebida ficar uniforme, fria e com textura de granizado fino. Não introduza colher enquanto estiver ligado nem sobrecarregue o copo. Conte o tempo real de pausas adicionais ou de outra rodada. Bater não elimina o álcool; esta versão o contém e não é apresentada como sem álcool.","image_url":"/recetas/receta-de-pina-colada/paso-04.webp","image_alt":"Liquidificador tampado com mistura de fruta e coco e gelo triturado"},{"title":"Divida sem adicionar enfeites","content":"Pare e tire o liquidificador da tomada. Com colher limpa, longe do aparelho em funcionamento, confira se não restam pedaços grandes de gelo ou fruta; se houver, tampe novamente e bata o necessário. Divida toda a mistura em 2 copos de pelo menos 350 ml de capacidade, alternando pequenas quantidades para distribuir polpa e gelo de forma semelhante. Cada porção proposta é aproximadamente metade do lote, sem peso ou volume final comprovados. Fatias de abacaxi, cerejas, chantili, açúcar e gelo de serviço não entram na nutrição desta fórmula. Espuma ou leve separação não comprovam falha nem garantem textura testada.","image_url":"/recetas/receta-de-pina-colada/paso-05.webp","image_alt":"Copo destacado do liquidificador parado vertendo em um dos dois copos"},{"title":"Sirva imediatamente e registre os tempos reais","content":"Sirva as 2 porções na hora com utensílios limpos. A proposta estima 15 minutos de preparo, 0 de cozimento e 15 minutos totais, incluindo lavagem, corte, pesagem, batimento e divisão; some pausas ou rodadas extras reais. Não há descanso obrigatório nem teste de cozinha declarado. Se não consumir prontamente, guarde tampado a 4 °C ou menos e use dentro de 1 dia; gelo derretido e coco separado mudam a textura e exigem misturar novamente. Refrigere em até 2 horas fora do frio, ou 1 hora se o ambiente superar 32 °C. Álcool não substitui higiene nem torna a bebida uma conserva estável. Identifique claramente a versão com rum.","image_url":"/recetas/receta-de-pina-colada/portada.webp","image_alt":"Dois copos de piña colada amarelo-clara sem enfeites ou chantili"}],"notes":"Proposta batida com fruta, suco, creme de coco adoçado e rum, sem reproduzir exatamente proporções IBA nem afirmar teste culinário. Contém álcool e é identificada como bebida para adultos; bater e refrigerar não o eliminam. Prepare e rotule separadamente uma variante sem rum, defina quantidades e recalcule sem reutilizar estes valores. Creme de coco adoçado para coquetéis difere de leite de coco ou creme natural: confira embalagem, alérgenos e possíveis laticínios adicionados. Use gelo de água potável e liquidificador apropriado. Pare e tire da tomada antes de abrir ou raspar perto das lâminas. Lave o abacaxi antes de descascar e separe utensílios de carnes cruas. Sirva prontamente; sobras tampadas a 4 °C ou menos, consumidas dentro de 1 dia com perda de textura. Refrigere em até 2 horas fora do frio ou 1 hora acima de 32 °C. Rum não conserva a bebida de modo estável fora da geladeira. Registre e recalcule mudanças de creme, suco, rum ou gelo; enfeites à parte. Duas porções e 15 minutos são propostas não testadas.","nutrition":{"calories":254.1,"protein_g":1.0,"carbs_g":35.4,"fat_g":5.1,"saturated_fat_g":4.7,"sodium_mg":13.5,"fiber_g":1.1,"sugar_g":30.3,"alcohol_g":10.0,"estimated":true,"source":"USDA FoodData Central — SR Legacy (abril de 2018)","source_url":"https://fdc.nal.usda.gov/download-datasets/","inputs":[{"ingredient":"piña fresca,120 g netos sin piel ni centro duro","edible_grams":120,"fdc_id":169124,"fdc_description":"Pineapple, raw, all varieties","per_100g":{"protein_g":0.54,"sodium_mg":1.0,"sugar_g":9.85,"fat_g":0.12,"fiber_g":1.4,"saturated_fat_g":0.009,"carbs_g":13.1,"calories":50.0,"alcohol_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/169124/nutrients"},{"ingredient":"zumo de piña envasado sin azúcar añadido, sin concentrar","edible_grams":180,"fdc_id":169947,"fdc_description":"Pineapple juice, canned or bottled, unsweetened, without added ascorbic acid","per_100g":{"saturated_fat_g":0.008,"carbs_g":12.9,"calories":53.0,"alcohol_g":0.0,"fat_g":0.12,"sugar_g":9.98,"fiber_g":0.2,"sodium_mg":2.0,"protein_g":0.36},"source_url":"https://fdc.nal.usda.gov/food-details/169947/nutrients"},{"ingredient":"crema de coco enlatada ENDULZADA para cócteles","edible_grams":60,"fdc_id":170171,"fdc_description":"Nuts, coconut cream, canned, sweetened","per_100g":{"alcohol_g":0.0,"saturated_fat_g":15.5,"fiber_g":0.2,"protein_g":1.17,"sodium_mg":36.0,"sugar_g":51.5,"fat_g":16.3,"carbs_g":53.2,"calories":357},"source_url":"https://fdc.nal.usda.gov/food-details/170171/nutrients"},{"ingredient":"ron blanco80proof/40%vol,60g pesados","edible_grams":60,"fdc_id":174817,"fdc_description":"Alcoholic beverage, distilled, rum, 80 proof","per_100g":{"fiber_g":0.0,"sodium_mg":1.0,"protein_g":0.0,"alcohol_g":33.4,"saturated_fat_g":0.0,"fat_g":0.0,"carbs_g":0.0,"calories":231,"sugar_g":0.0},"source_url":"https://fdc.nal.usda.gov/food-details/174817/nutrients"}],"serving_size":"Metade do lote; 2 porções propostas","method":"Quatro fichas USDA verificadas: gramas comestíveis multiplicados pelos nutrientes por 100 g, somados e divididos por 2. Abacaxi fresco FDC 169124, suco embalado sem açúcar adicionado FDC 169947, creme de coco ADOÇADO FDC 170171 e rum 80 proof FDC 174817. Energia USDA inclui álcool, não apenas proteínas, gorduras e carboidratos. Gelo de água potável 180 g sem aporte nestes campos.","note":"Estimativa, não análise nem rendimento confirmado. Inclui todo o rum, sem supor evaporação ou eliminação ao bater. Álcool estimado 10,0 g por porção pela ficha do rum, não graduação final medida nem promessa de consumo seguro. Creme adoçado difere de leite ou creme natural; marca, açúcar, graduação e quantidades mudam os valores. Toda a polpa sem coar. Gelo 180 g incluído apenas no peso inicial de 600 g, não em volume final medido nem porção servida de 300 g comprovada. Exclui enfeites e acompanhamentos; todos os dados presentes, ausências nunca substituídas por zero."},"keywords":["piña colada com rum","piña colada batida","creme de coco adoçado","coquetel de abacaxi"],"image_url":"/recetas/receta-de-pina-colada/portada.webp","gallery":["/recetas/receta-de-pina-colada/paso-01.webp","/recetas/receta-de-pina-colada/paso-02.webp","/recetas/receta-de-pina-colada/paso-03.webp","/recetas/receta-de-pina-colada/paso-04.webp","/recetas/receta-de-pina-colada/paso-05.webp"],"seo":{"title":"Piña colada com rum: quantidades e etapas para bater","description":"Abacaxi fresco, suco, creme de coco adoçado, rum branco e gelo medido: duas porções propostas, preparo em etapas e nutrição incluindo álcool.","image_alt":"Dois copos transparentes de piña colada amarelo-clara, cremosa e gelada, sem fatias de abacaxi, cerejas ou chantili acrescentado","image_variants":["/recetas/receta-de-pina-colada/portada-1x1.webp","/recetas/receta-de-pina-colada/portada-4x3.webp","/recetas/receta-de-pina-colada/portada-16x9.webp"],"faq":[{"q":"Creme de coco adoçado equivale a leite de coco?","a":"Não. A fórmula usa 60 g de creme de coco adoçado para coquetéis com ficha USDA específica. Leite de coco, creme sem açúcar e creme de leite mudam açúcar, gordura, sabor e textura; não substitua mantendo os mesmos valores."},{"q":"Posso fazer uma versão sem álcool?","a":"Sim, como variante separada: omita o rum, defina e registre eventual líquido substituto e recalcule. Não adicione rum a essa variante nem chame uma bebida com rum de sem álcool depois de bater: o batimento não elimina álcool. Estas calorias não valem para outra fórmula."},{"q":"Por que fica mais líquida ao esperar?","a":"O gelo derrete e o coco pode se separar. Sirva recém-batida e registre água ou gelo extras. São previstos 180 g de gelo no lote; mudanças alteram diluição e peso das porções. Não se promete textura idêntica entre marcas e aparelhos."}]},"published":true,"editorial_status":"published","content_html":"<p>Proposta de piña colada batida com abacaxi fresco, suco, creme de coco adoçado, rum branco e gelo medido. Prevê 2 porções e 15 minutos de preparo, sem cozimento. Contém álcool; quantidades, textura e rendimento ainda precisam de teste na cozinha. A nutrição inclui a energia do rum e exclui enfeites.</p><p>Proposta batida com fruta, suco, creme de coco adoçado e rum, sem reproduzir exatamente proporções IBA nem afirmar teste culinário. Contém álcool e é identificada como bebida para adultos; bater e refrigerar não o eliminam. Prepare e rotule separadamente uma variante sem rum, defina quantidades e recalcule sem reutilizar estes valores. Creme de coco adoçado para coquetéis difere de leite de coco ou creme natural: confira embalagem, alérgenos e possíveis laticínios adicionados. Use gelo de água potável e liquidificador apropriado. Pare e tire da tomada antes de abrir ou raspar perto das lâminas. Lave o abacaxi antes de descascar e separe utensílios de carnes cruas. Sirva prontamente; sobras tampadas a 4 °C ou menos, consumidas dentro de 1 dia com perda de textura. Refrigere em até 2 horas fora do frio ou 1 hora acima de 32 °C. Rum não conserva a bebida de modo estável fora da geladeira. Registre e recalcule mudanças de creme, suco, rum ou gelo; enfeites à parte. Duas porções e 15 minutos são propostas não testadas.</p>"}]$records$::jsonb;
 b constant jsonb := $before${"id":"1b078b4e-6544-41d5-8e9c-52e6d8fa3d8e","recipe_group_id":"e91765d0-3d25-4790-a08f-89ce82446332","slug":"receta-de-pina-colada","public_path":"/receta-de-pina-colada","source_url":"https://manualdecocina.com/receta-de-pina-colada/","created_at":"2026-09-23T20:50:30.015432+00:00","published_at":"2026-09-23T20:50:30.015432+00:00","expected_row_md5":"5f8c556c3a86ef05410b815dbff15f90"}$before$::jsonb;
 g constant uuid := 'e91765d0-3d25-4790-a08f-89ce82446332';
 outside_checksum text;
 es_count int;
 n int;
BEGIN
 IF current_setting('manualdecocina.batch03_gate',true) IS DISTINCT FROM 'ready15_deployed' THEN
  RAISE EXCEPTION 'Full15recipe lote03 publication/deployment gate not supplied';
 END IF;
 PERFORM id FROM public.recipes WHERE recipe_group_id=g ORDER BY id FOR UPDATE;
 IF jsonb_array_length(j)<>7 OR (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(j)x)<>7
  OR (SELECT count(DISTINCT x->>'language') FROM jsonb_array_elements(j)x)<>7
  OR (SELECT count(DISTINCT x->>'public_path') FROM jsonb_array_elements(j)x)<>7 THEN
  RAISE EXCEPTION 'Invalid pina_colada payload';
 END IF;
 IF EXISTS(SELECT 1 FROM public.recipes r WHERE r.id=(b->>'id')::uuid AND
   (r.recipe_group_id<>g OR r.language<>'es' OR r.slug<>b->>'slug' OR r.public_path<>b->>'public_path'
    OR r.source_url IS DISTINCT FROM b->>'source_url' OR r.created_at<>(b->>'created_at')::timestamptz
    OR r.published_at IS DISTINCT FROM (b->>'published_at')::timestamptz)) THEN
  RAISE EXCEPTION 'Historical identity/date divergence before idempotent or initial publication';
 END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(j)x WHERE (x->>'recipe_group_id')::uuid<>g
    OR x->>'language' NOT IN ('es','de','en','fr','it','ja','pt')) THEN
  RAISE EXCEPTION 'Unexpected group or language in publication payload';
 END IF;
 IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=g)=7
  AND NOT EXISTS(SELECT 1 FROM jsonb_populate_recordset(NULL::public.recipes,j)x LEFT JOIN public.recipes r ON r.id=x.id
    WHERE r.id IS NULL OR NOT r.published OR r.editorial_status<>'published' OR r.recipe_group_id<>x.recipe_group_id
      OR r.language<>x.language OR r.slug<>x.slug OR r.public_path<>x.public_path OR r.title IS DISTINCT FROM x.title OR r.excerpt IS DISTINCT FROM x.excerpt OR r.summary IS DISTINCT FROM x.summary OR r.ingredients IS DISTINCT FROM x.ingredients OR r.steps IS DISTINCT FROM x.steps OR r.category IS DISTINCT FROM x.category OR r.prep_time_minutes IS DISTINCT FROM x.prep_time_minutes OR r.cook_time_minutes IS DISTINCT FROM x.cook_time_minutes OR r.total_time_minutes IS DISTINCT FROM x.total_time_minutes OR r.servings IS DISTINCT FROM x.servings OR r.image_url IS DISTINCT FROM x.image_url OR r.content_html IS DISTINCT FROM x.content_html OR r.notes IS DISTINCT FROM x.notes OR r.difficulty IS DISTINCT FROM x.difficulty OR r.course IS DISTINCT FROM x.course OR r.cuisine IS DISTINCT FROM x.cuisine OR r.keywords IS DISTINCT FROM x.keywords OR r.nutrition IS DISTINCT FROM x.nutrition OR r.gallery IS DISTINCT FROM x.gallery OR r.seo IS DISTINCT FROM x.seo OR r.source_url IS DISTINCT FROM x.source_url) THEN
  RAISE NOTICE 'Pina colada already matches7/7; no mutation'; RETURN;
 END IF;
 IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=g)<>1
  OR NOT EXISTS(SELECT 1 FROM public.recipes r WHERE r.id=(b->>'id')::uuid AND r.recipe_group_id=g
    AND r.language='es' AND NOT r.published AND md5(to_jsonb(r)::text)=b->>'expected_row_md5') THEN
  RAISE EXCEPTION 'Reserved pina_colada state changed; reconcile before retry';
 END IF;
 IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_populate_recordset(NULL::public.recipes,j)x
  ON r.id=x.id OR r.public_path=x.public_path OR (r.language=x.language AND r.slug=x.slug)
  WHERE r.id<>x.id OR r.recipe_group_id<>x.recipe_group_id OR r.language<>x.language) THEN
  RAISE EXCEPTION 'Pina colada recipe identity/route collision';
 END IF;
 IF EXISTS(SELECT 1 FROM public.content_pages c JOIN jsonb_populate_recordset(NULL::public.recipes,j)x
  ON c.public_path=x.public_path OR (c.language=x.language AND c.slug=x.slug)) THEN
  RAISE EXCEPTION 'Pina colada content_page route collision';
 END IF;
 SELECT md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' ORDER BY r.id),'')) INTO outside_checksum
  FROM public.recipes r WHERE r.recipe_group_id<>g;
 SELECT count(*) INTO es_count FROM public.recipes WHERE language='es' AND published;
 UPDATE public.recipes r SET title=x.title, excerpt=x.excerpt, summary=x.summary, ingredients=x.ingredients, steps=x.steps, category=x.category, prep_time_minutes=x.prep_time_minutes, cook_time_minutes=x.cook_time_minutes, total_time_minutes=x.total_time_minutes, servings=x.servings, image_url=x.image_url, content_html=x.content_html, notes=x.notes, difficulty=x.difficulty, course=x.course, cuisine=x.cuisine, keywords=x.keywords, nutrition=x.nutrition, gallery=x.gallery, seo=x.seo,editorial_status='published',ready_at=now(),published=true
  FROM jsonb_populate_recordset(NULL::public.recipes,j)x WHERE r.id=x.id AND x.language='es';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>1 THEN RAISE EXCEPTION 'Expected1ES update, got%',n; END IF;
 INSERT INTO public.recipes(id,recipe_group_id,language,slug,public_path,source_url,title,excerpt,summary,ingredients,steps,category,prep_time_minutes,cook_time_minutes,total_time_minutes,servings,image_url,content_html,notes,difficulty,course,cuisine,keywords,nutrition,gallery,seo,editorial_status,ready_at,published) SELECT x.id,x.recipe_group_id,x.language,x.slug,x.public_path,x.source_url,x.title,x.excerpt,x.summary,x.ingredients,x.steps,x.category,x.prep_time_minutes,x.cook_time_minutes,x.total_time_minutes,x.servings,x.image_url,x.content_html,x.notes,x.difficulty,x.course,x.cuisine,x.keywords,x.nutrition,x.gallery,x.seo,'published',now(),true FROM jsonb_populate_recordset(NULL::public.recipes,j)x WHERE x.language<>'es';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>6 THEN RAISE EXCEPTION 'Expected6translations, got%',n; END IF;
 IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=g)<>7
  OR (SELECT count(DISTINCT language) FROM public.recipes WHERE recipe_group_id=g AND published AND editorial_status='published')<>7
  OR EXISTS(SELECT 1 FROM jsonb_populate_recordset(NULL::public.recipes,j)x LEFT JOIN public.recipes r ON r.id=x.id
    WHERE r.id IS NULL OR r.recipe_group_id<>x.recipe_group_id OR r.language<>x.language
      OR r.slug<>x.slug OR r.public_path<>x.public_path OR NOT r.published OR r.title IS DISTINCT FROM x.title OR r.excerpt IS DISTINCT FROM x.excerpt OR r.summary IS DISTINCT FROM x.summary OR r.ingredients IS DISTINCT FROM x.ingredients OR r.steps IS DISTINCT FROM x.steps OR r.category IS DISTINCT FROM x.category OR r.prep_time_minutes IS DISTINCT FROM x.prep_time_minutes OR r.cook_time_minutes IS DISTINCT FROM x.cook_time_minutes OR r.total_time_minutes IS DISTINCT FROM x.total_time_minutes OR r.servings IS DISTINCT FROM x.servings OR r.image_url IS DISTINCT FROM x.image_url OR r.content_html IS DISTINCT FROM x.content_html OR r.notes IS DISTINCT FROM x.notes OR r.difficulty IS DISTINCT FROM x.difficulty OR r.course IS DISTINCT FROM x.course OR r.cuisine IS DISTINCT FROM x.cuisine OR r.keywords IS DISTINCT FROM x.keywords OR r.nutrition IS DISTINCT FROM x.nutrition OR r.gallery IS DISTINCT FROM x.gallery OR r.seo IS DISTINCT FROM x.seo OR r.source_url IS DISTINCT FROM x.source_url) THEN
  RAISE EXCEPTION 'Pina colada7/7 final content verification failed';
 END IF;
 IF EXISTS(SELECT 1 FROM public.recipes r WHERE r.id=(b->>'id')::uuid AND
   (r.slug<>b->>'slug' OR r.public_path<>b->>'public_path' OR r.source_url IS DISTINCT FROM b->>'source_url'
    OR r.created_at<>(b->>'created_at')::timestamptz OR r.published_at IS DISTINCT FROM (b->>'published_at')::timestamptz)) THEN
  RAISE EXCEPTION 'Pina colada historical identity/date preservation failed';
 END IF;
 IF outside_checksum IS DISTINCT FROM(SELECT md5(coalesce(string_agg(md5(to_jsonb(r)::text),'' ORDER BY r.id),'')) FROM public.recipes r WHERE r.recipe_group_id<>g)
  OR (SELECT count(*) FROM public.recipes WHERE language='es' AND published)<>es_count+1 THEN
  RAISE EXCEPTION 'Unexpected change outside pina_colada group';
 END IF;
 RAISE NOTICE 'Pina colada verified7/7 within surrounding atomic lote03 transaction';
END
$pina_colada$;
